We choose two rationally independent positive real numbers $\alpha,\beta>0$ (e.g. $\alpha=1,\beta=\sqrt{2}$), and define the score function $P : \cE{G} \times \cE{H} \to \R$ as follows:
\[
P(e,f) = \begin{cases}
    \alpha & \textrm{if } (e, f )= \left(e^+,f^+\right), \\
    -\alpha & \textrm{if } (e,f)=\left(e^+,f^-\right), \\
    \beta & \textrm{if } (e,f)=\left(e^-,f^-\right), \\
    -\beta & \textrm{if } (e,f)=\left(e^-,f^+\right), \\
    0 & \textrm{otherwise.}
  \end{cases}
\]

Starting from the initial vertex $Y$, Bob can only choose between two infinite walks \linebreak$\left(f^a,f^-, f^-, \ldots\right), \left(f^b,f^+, f^+, \ldots\right)$.
If Alice's strategy is to choose an eventually periodic walk $(e_j)_{j = 1}^\infty$, then the following limits exist: 
\begin{equation}\label{eq:p_plus_minus}
p_+:= \lim_{n \to \infty}\frac{1}{n}\#\{1\le j \le n~:~ e_j = e^{+}\} \mbox{ and } p_- := \lim_{n \to \infty}\frac{1}{n}\#\{1\le j \le n~:~ e_j = e^{-}\}.    
\end{equation}
If the sequence $(e_j)_{j = 1}^\infty$ is eventually periodic, then $p_+,p_-$ are rational numbers such that $p_+ + p_-=1$. 
In this case, the payoff is $\pm \left( \alpha p_+ - \beta p_- \right)$,
depending on Bob's choice of walk.
So Bob can secure a payoff of at most
\[- |\alpha p_+ - \beta p_- |.\]
Since $p_+, p_-$ are rational and sum to $1$, the linear independence of $\alpha,\beta$ over $\mathbb{Q}$ implies that $\alpha p_+ - \beta p_- \ne 0$, so whenever Alice's strategy chooses an eventually periodic output, Bob can secure a strictly negative payoff.
On the other hand, Alice can choose a non-eventually periodic walk $(e_j)_{j = 1}^\infty$ such that
the limits in \eqref{eq:p_plus_minus} exist, and $\alpha p_+ = \beta p_-$, in which case the payoff will be $0$, regardless of Bob's strategy. This proves that there is no eventually periodic Nash equilibrium.
\end{example}

\begin{example}\label{ex:integer_valued_counterexample}
\begin{figure}
\begin{tikzpicture}[node distance = 20mm, main/.style = {draw, circle}] 
\node[main] (1) {$M$};
\node[main] (2) [below of=1] {$X$}; 
\node[main] (3) [right of=2] {$Y$};
\node[main] (4) [right of=3] {$Z$};
\node[main] (5) [above of=4] {$P$};

\Loop[dist=1cm,dir=NOWE,label=$e^{-}$,labelstyle=above left](1)  
\Loop[dist=1cm,dir=NOEA,label=$e^{+}$,labelstyle=above right](5)
\Loop[dist=1cm,dir=SOWE, label=$f^{-}$,labelstyle=below left](2)
\Loop[dist=1cm,dir=SOEA, label=$f^+$, labelstyle=below right](4)

\draw[->] (3) to node [above] {$f^a$} (2);
\draw[->] (3) to node [above] {$f^b$} (4);
\draw[->] (1) to [out=15, in=165] node [above] {$e^a$} (5);
\draw[->] (5) to [out=195, in=345] node [below] {$e^b$} (1);
\end{tikzpicture}
\caption{Pictured here are the graphs $G, H$ referenced in \Cref{ex:irrational_example}, where the top row depicts the graph $G$ with vertices $\cV{G} = \{P, M\}$, and the bottom row depicts a graph $H$ with vertice $\cV{H} = \{X, Y, Z\}$.}
\label{fig:no_periodic_winning_strat_in_non_alt_but_rational}
\end{figure}
Let $G, H$ be the graphs depicted in \Cref{fig:no_periodic_winning_strat_in_non_alt_but_rational}, and let  $P : \cE{G} \times \cE{H} \to \Z$ to be the function
\[
P(e, f) = \begin{cases}
1 & \textrm{if } (e,f) \in \left\{ \left(e^+,f^+\right), \left(e^-,f^-\right) \right\}, \\
-1  & \textrm{otherwise.}
\end{cases}
\]
As in \Cref{ex:irrational_example}, if Bob starts from the initial vertex $Y$, then he can only choose between the infinite walks $\left( f^a,f^-,f^-,\ldots\right), \left( f^b,f^+,f^+,\ldots\right)$.
If Alice's strategy is to choose an eventually periodic walk $(e_j)_{j = 1}^\infty$, then the limits $p_+, p_-$ exist, as does the limit $p_0 : = \lim_{n \to \infty} \frac{1}{n} \# \left\{ 1 \leq j \leq n ~ : e_j \not \in \left\{ e^+, e^- \right\} \right\}$.
It also follows that $p_+,p_-,p_0 \geq 0$ and $p_+ + p_- + p_0 = 1$.
Furthermore, unless $e_j \in \left\{ e^+, e^- \right\}$ for all sufficiently large $n \in \N$, we have that $p_0>0$, because every period must contain a ``transition edge" between $e^+$ and $e^-$.
In either case, Bob can secure a payoff of
\[
-p_0 -|p_+-p_-|,
\]
which is strictly negative.
On the other hand, Alice can choose a (non-eventually periodic) walk $(e_j)_{j = 1}^\infty$ such that $p_+=p_-=\frac{1}{2}$ and $p_0=0$, e.g.
\[
\left( e^-,e^a,e^+,e^b,e^-,e^-,e^a,e^+,e^+,e^b,\ldots,\underbrace{e^-,\ldots,e^-}_n,e^a,\underbrace{e^+,\ldots,e^+}_n,e^b,\ldots \right).
\]
In this case, the payoff will be $0$, regardless of Bob's strategy, again proving that there is no eventually periodic Nash equilibrium in this example.
\end{example}

