        >>> iters = 10
        >>> 
        >>> for iter in range(iters):
        >>> 
        >>>     x_new = bo(x_train, y_train)
        >>> 
        >>>     y_new = black_box(x_new)
        >>> 
        >>>     x_train = torch.vstack((x_train, x_new))
        >>>     y_train = torch.hstack((y_train, y_new))
