\subsection{Main Results}
\label{ssec: main-results}
Consider an $M/M/n$ queue with arrival rate $\lambda_n = n-n^{1-\alpha}$ for some $\alpha \in \R^+$ and service rate $\mu=1$ (unless stated otherwise). Such a parametrization of $\lambda$ is popularly known as the many-server-heavy-traffic regime and queueing systems are generally analyzed for $t, n \rightarrow \infty$. On the contrary, here we focus on a finite $t$ and a finite $n$. We obtain a bound on $\chi(\pi_{n, t}, \nu_n)$ of the form $e^{-\square t}$, thus, establishing the convergence of the finite-time queue length distribution $\pi_{n, t}$ to the stationary distribution $\nu_n$ as $t \rightarrow \infty$. Moreover, we provide a tight bound on the mixing rate, denoted by $\square$. This result is established in the following theorem.

% \textcolor{red}{In this section, we wish to give a bound on the distance to stationarity using the Chi-square distance between $\pi_{n,t}$, the queue length distribution at time $t$, and the stationary distribution $\nu_n$. As $t \rightarrow \infty$, we have $\pi_{n,t} \rightarrow \nu_n$, which gives $\nu_n = \pi_{n,\infty}$ and $\pi_{n,0}$ as the initial distribution. Furthermore, from the definition of $P_t$, we also have $\pi_{n,t} = \pi_{n,0} P_t$. The following theorem establishes an exponential convergence rate of $\pi_{n,t}$ to $\nu_n$ in terms of Chi-square distance in the form of $e^{-\square t}$. Here, we denote $\square$ as the mixing rate, and our result provides a tight characterization of the transient behavior of an $M/M/n$ queue. Now that we have established the model, we shall state our main Theorem as follows.} 


% \textcolor{red}{Universal Theorem here}


\begin{theorem}
\label{thm: unifying-theorem}
    Let $\pi_{n,t}$ be the queue length distribution at time $t$ of the continuous-time $M/M/n$ system with the arrival rate $\lambda_n = n - n^{1-\alpha}$ and service rate $1$ and let the stationary distribution be $\nu_n$. 
    % \textcolor{red}{Write $\chi(\pi_{n,t},\nu_n) \leq e^{-\square t} \chi(\pi_{n,0},\nu_n)$ and then for each regime specify what is $\square$}
    For $\alpha \geq 1$, we have that:
    \begin{align}
        \label{eqn: super-nds-mixing-bound}
        \chi(\pi_{n,t},\nu_n) \leq e^{-(\sqrt{n}-\sqrt{\lambda_n})^2 t} \chi(\pi_{n,0},\nu_n) \, \forall t \geq 0.
    \end{align}
    For $\alpha \in (1/2,1)$ and $n \geq 65$, we have that:
    \begin{align}
        \label{eqn: super-halfin-whitt-mixing-bound}
        \chi(\pi_{n,t},\nu_n) \leq e^{-C_n (\sqrt{n}-\sqrt{\lambda_n})^2 t} \chi(\pi_{n,0},\nu_n) \, \forall t \geq 0,
    \end{align}
    % where $C_n = \frac{1}{1+C_b}$ and $C_b =  \frac{2^5 3^8 e^{\frac{13}{6}} \sqrt{6 \pi}}{77^2} n^{\frac{3}{2}-3\alpha} + \frac{2^{10} \times 3^{14} e^{\frac{13}{3}} \sqrt{6\pi}}{7^5 \times 11^4} n^{\frac{5}{2}-5\alpha}$.    
    for some $C_n > 0$ such that $\lim_{n \rightarrow \infty} C_n = 1$.

    For $\alpha \in (0,1/2)$ and a sufficiently large $n$ such that $\lambda_n \geq 3$, we have that:
    \begin{align}
        \label{eqn: sub-halfin-whitt-mixing-bound}
        \chi(\pi_{n,t},\nu_n) \leq e^{-D_n t} \chi(\pi_{n,0},\nu_n) \, \forall t \geq 0,
    \end{align}
    for some $D_n > 0$ such that $\lim_{n \rightarrow \infty} D_n = 1/25$. 
    % \textcolor{red}{Mention that $D_n \rightarrow 1/25$ and say that we off by a constant factor. Moreover, we have $D_n = \gamma_n/129 > d$. We have not tried to optimize the constant}
    % Moreover, let $\{\lambda_n\}$ be a sequence of arrival rates such that
    % \begin{align*}
    %     \lim_{n \rightarrow \infty} \frac{\log\br{n-\lambda_n}}{\log n} = 1-\alpha.
    % \end{align*}
    % Then, we have
    % \begin{align*}
    %     \chi(\pi_{n,t},\nu_n) \leq e^{-D_n t} \chi(\pi_{n,0},\nu_n)
    % \end{align*}
    % such that $D_n > 0$ and $\lim_{n \rightarrow \infty} D_n = 1$.

    Finally, for $\alpha = 1/2$ and $n \geq 65$, we have 
    \begin{align}
        \label{eqn: halfin-whitt-mixing-bound}
        \chi(\pi_{n,t},\nu_n) \leq e^{-\frac{t}{1387444804}} \chi(\pi_{n,0},\nu_n) \, \forall t \geq 0.
    \end{align}
\end{theorem}

% demonstrate our method for the $M/M/n$ system. 

