\begin{prop}
    \label{thm: mm1-mixing}
    Let $\pi_{t, 1}$ be the queue length distribution at time $t \in \R^+$ of the continuous-time $M/M/1$ system with the arrival rate $\lambda$ and service rate $\mu$ such that $0 < \lambda < \mu$ and let the stationary distribution be $\nu_1$, we have:
    \begin{align*}
        \chi(\pi_{t,1},\nu_1) \leq e^{- (\sqrt{\mu}-\sqrt{\lambda})^2 t} \chi(\pi_{0,1},\nu_1) \, \forall t \geq 0.
    \end{align*}
\end{prop}

