\begin{prop}
    \label{thm: mminf-mixing} 
    Let $\pi_{t, \infty}$ be the queue length distribution at time $t$ of the continuous-time $M/M/\infty$ system with the arrival rate $\lambda > 0$ and the service rate $\mu > 0$ such that $\lambda/\mu \in \Z^+$ and let the stationary distribution be $\nu_\infty$, we have:
    \begin{align*}
        \chi(\pi_{t, \infty},\nu_\infty) \leq e^{-\mu t} \chi(\pi_{0, \infty},\nu_\infty) \, \forall t \geq 0.
    \end{align*}
\end{prop}

