\subsubsection{Finite-time statistics}
\label{sssec: finite-time statistics}
From the established mixing bounds in Theorem \ref{thm: unifying-theorem}, we obtain finite-time statistics like the mean and tail. We start with the mean queue length below.

% \begin{restatable}{cor}{meanqueuelengthcorollary}
\begin{corollary}
\label{corollary: mean-queue-length-mmn}
Let $\pi_{n,t}$ be the queue length distribution at time $t$ of the continuous-time $M/M/n$ system with the arrival rate $\lambda_n = n - n^{1-\alpha}$ and a service rate $1$ whose stationary distribution be $\nu_n$. For $\alpha \geq 1$, we have that
\begin{align}
    \left| \E_{\pi_{n,t}}[q] - \E_{\nu_n}[q] \right| \leq e^{-(\sqrt{n}-\sqrt{\lambda_n})^2 t} \sqrt{2}\br{n+n^\alpha} \chi(\pi_{n,0}, \nu_n).
\end{align}

For $\alpha \in (1/2, 1)$, we have
\begin{align}
    \left| \E_{\pi_{n,t}}[q] - \E_{\nu_n}[q] \right| \leq e^{- C_n (\sqrt{n}-\sqrt{\lambda_n})^2 t} \sqrt{2}\br{n+n^\alpha} \chi(\pi_{n,0}, \nu_n)
\end{align}
for some $C_n > 0$ such that $\lim_{n \rightarrow \infty} C_n = 1$.

For $\alpha \in (0,1/2)$, we have
\begin{align}
    \left| \E_{\pi_{n,t}}[q] - \E_{\nu_n}[q] \right| \leq e^{- D_n t} \sqrt{2}\br{n+n^\alpha} \chi(\pi_{n,0}, \nu_n)
\end{align}
for some $D_n > 0$ such that $\lim_{n \rightarrow \infty} D_n = 1/25$.

And finally, if $\lambda_n$ is a sequence of arrival rates such that $\lim_{n \rightarrow \infty} \frac{\lambda_n}{n} = 0$, then we have
\begin{align}
    \left| \E_{\pi_{n,t}}[q] - \E_{\nu_n}[q] \right| \leq e^{- L_n t} n \chi(\pi_{n,0}, \nu_n)
\end{align}
for some $L_n > 0$ such that $\lim_{n \rightarrow \infty} L_n = 1$.
\end{corollary}
% \end{restatable}

One can prove Corollary \ref{corollary: mean-queue-length-mmn} by combining the Theorem \ref{thm: unifying-theorem} and Corollary \ref{corollary: moment-bound} for $k = 1$. We defer the details of the proof to Appendix \ref{ssec: mean-queue-length-mmn-proof}. Similar to the above corollary, we can obtain bounds on any moment $k \in \Z^+$ by Corollary \ref{corollary: moment-bound} combined with a $2k$-moment bound on the steady-state distribution $\nu_n$. Moreover, in addition to the mean queue length bound, we can establish some tail-bound results to gain some understanding on the concetration of the finite-time behavior of the queue length distribution as follows.

\begin{corollary}
\label{corollary: tail-bounds}
Let $\pi_{n,t}, \nu_n$ be the queue length distribution at time $t$ and the stationary distribution of the $M/M/n$ system with arrival rate $\lambda_n = n-n^{1-\alpha_n}$ and unit service rate respectively, and let $\varepsilon = 1-\frac{\lambda_n}{n}$ and $q$ be the random variable denoting the queue length. For $n \geq n_0, \delta \in (0,+\infty)$ and $n_0$ is a constant dependent on the regime, we have
\begin{align*}
    \P_{\pi_{n,t}}\sqbr{\varepsilon_n \br{q-n} > x} \leq \br{1+\chi(\pi_{n,t}, \nu_n)} \sqrt{ex} e^{-\frac{x}{2}}
\end{align*}
In particular, for $\alpha_n = \alpha \in [1,\infty)$, we have
\begin{align*}
    \P_{\pi_{n,t}}\sqbr{\varepsilon_n \br{q-n} > x} &\leq \br{1 + e^{-(\sqrt{n}-\sqrt{\lambda_n})^2 t} \chi(\pi_{n,0}, \nu_n)} \sqrt{ex} e^{-\frac{x}{2}}.
\end{align*}

For $\alpha_n = \alpha \in (1/2,1)$, we have
\begin{align*}
    \P_{\pi_{n,t}}\sqbr{\varepsilon_n \br{q-n} > x} &\leq \br{1 + e^{-C_n (\sqrt{n}-\sqrt{\lambda_n})^2 t} \chi(\pi_{n,0}, \nu_n)} \sqrt{ex} e^{-\frac{x}{2}}
\end{align*}
where $C_n$ is a positive parameter such that $\lim_{n \rightarrow \infty} C_n = 1$.

For $\alpha_n = \alpha \in (0,1/2)$, we have 
% for a fixed constant $\delta > 0$
\begin{align*}
    \P_{\pi_{n,t}}\sqbr{\varepsilon\br{q-n} > x} &\leq \br{1+e^{-D_n t} \chi(\pi_{n,0}, \nu_n)}\sqrt{0.5e^{-\frac{2n^{1-2\alpha}}{7}} + 6 n^{2\alpha - 1}} \times \sqrt{ex} e^{-\frac{x}{2}}
    % \P_{\pi_{n,t}}\sqbr{\varepsilon\br{q-n} > x} &\leq \br{1+e^{-D_n t} \chi(\pi_{n,0}, \nu_n)}\sqrt{\frac{e^{-\frac{4n^{1-2\alpha}}{7(1+\delta)}} + \br{10 + \frac{2}{\delta}} n^{2\alpha - 1}}{1+\frac{1}{\delta}}} \times \sqrt{ex} e^{-\frac{x}{2}}
\end{align*}
where $D_n$ is a positive parameter such that $\lim_{n \rightarrow \infty} D_n = 1/25$.

And finally, if $\lambda_n$ is a sequence of arrival rates such that $\lim_{n \rightarrow \infty} \frac{\lambda_n}{n} = 0$ then we have
\begin{align*}
    \P_{\pi_{n,t}}\sqbr{q-n > x} &\leq \br{1+e^{-L_n t} \chi(\pi_{n,0}, \nu_n)} \sqrt{e^{-\frac{n^{1-\alpha_n}}{2}} + 4n^{\alpha_n-1} + \frac{8n^{2\alpha_n-1}}{e}} \times e^{-\frac{x}{2}}
\end{align*}
where $\lim_{n \rightarrow \infty} \alpha_n = 0$ and $L_n$ is a positive parameter such that $\lim_{n \rightarrow \infty} L_n = 1$.
\end{corollary}

The proof of Corollary \ref{corollary: tail-bounds} is deferred to Appendix \ref{sssec: tail-bounds-proof}. Note that if $q(t) \geq n$, then $q(t) - n$ is the number of waiting customers at time $t$. The results in Corollary \ref{corollary: tail-bounds} tell us what is the tail distribution of the number of waiting customers at time $t$. In the Sub-Halfin-Whitt regime, we have the pre-exponent term approaches $0$ as $n \rightarrow \infty$, which suggests a faster decay rate than exponential. Moreover, we can also estimate the probability of having an idle server at time $t$ as follows.

