\begin{assumption}
    \label{assumption: ctmc}
    The given CTMC is irreducible, aperiodic, positive recurrent, and reversible.
\end{assumption}

Assumption \ref{assumption: ctmc} implies that there exists a unique stationary distribution $\nu$ such that $\nu(x) \cL (x,y) = \nu(y) \cL(y,x)$ for all $x,y \in \cS$. 

\begin{defi} \label{def: poincare_inequality}
A CTMC admits a Poincar\'e constant $C_P$ if for all test function $f \in \ell_{2,\nu}$, we have
\begin{align}
    \label{eqn: poincare-inequality}
    \Var_\nu(f) \leq C_P \cE(f,f).
\end{align}   
\end{defi}
% Next, a CTMC admits a Poincar\'e constant $C_P$ if for all test function $f \in \ell_{2,\pi}$, we have
% \begin{align}
%     \label{eqn: poincare-inequality}
%     \Var_\pi(f) \leq C_P \cE(f,f).
% \end{align}
Here, the Dirichlet form $\cE(f,f)$ is defined as:
\begin{align}
    \label{eqn: dirichlet-form}
    \cE(f,f) = \langle f,-\cL f\rangle_\nu = -\sum_{x,y \in \cS} \nu(x)\cL(x,y) f(x)f(y).
\end{align}
It is known that Poincar\'e inequalities immediately imply exponential ergodicity of the CTMC \cite{Bakry2013AnalysisAGMarkovDiffusionbook}. We formally state it in the following proposition for completeness.

% One way to establish mixing time results is to establish the Poincar\'e inequality. We have the following Proposition that shows the equivalence between Poincar\'e inequalities and mixing.

\begin{prop}
    \label{prop: poincare-equals-mixing}
    % Let $P_t$ be a Markov semigroup with a stationary measure $\pi$. 
    Under Assumption \ref{assumption: ctmc}, if the system admits the Poincar\'e inequality \eqref{eqn: poincare-inequality} with constant $C_P$, then
    \begin{align}
        \label{eqn:chi-square-convergence}
        % \norm{P_t f - \pi f}_{2,\pi} &\leq e^{-t/C_P} \norm{f - \pi f}_{2,\pi}
        \chi^2\br{\pi_t,\nu} \leq e^{-\frac{2t}{C_P}} \chi^2(\pi_0,\nu)
    \end{align}
    where $\pi_t$ is distribution at time $t$ and $\nu$ is the stationary distribution.
\end{prop}

The proof of Proposition \ref{prop: poincare-equals-mixing} is well-known and can be found in \cite{Bakry2013AnalysisAGMarkovDiffusionbook} and in Appendix \ref{ssec:mixing-prop-proof}. Proposition \ref{prop: poincare-equals-mixing} shows that Poincar\'e inequality with constant $C_P$ implies exponential convergence in the chi-square distance with mixing rate $1/C_P$. Thus, for the rest of the section, our focus is on establishing the Poincar\'e constant.

