% Recent developments on Markov chain mixing \cite{taghvaei-lyapunov-poincare, andrieu2022poincaresurvey} have allowed us to use Lyapunov drifts to establish Poincar\'e inequalities. There are two main ingredients in a Lyapunov-Poincar\'e mixing proof. The first one is the Foster-Lyapunov assumption: 
Building on the recent developments on Markov chain mixing \cite{taghvaei-lyapunov-poincare, andrieu2022poincaresurvey}, we now present the Lyapunov-Poincar\'e methodology below, which has two main ingredients. The first one is a Foster-Lyapunov \emph{like} assumption:
\begin{assumption}
\label{assumption: foster-lyapunov}
% An irreducible continuous-time Markov chain on a countable state space with the generator $\cL$ is said to satisfy 
There exists a Lyapunov function $V: \cS \rightarrow [1,\infty)$ along with $b: \cS \rightarrow [0,\infty)$ and $\gamma > 0$ such that
\begin{align}
    \label{eqn: foster-lyapunov}
    \cL V(q) \leq - \gamma V(q) + b(q) \, \forall q \in \cS.
\end{align}
\end{assumption}
For the special case of $b = B 1_K$ for some finite $K \subseteq S$ and $B>0$, the above is same as the classical Foster-Lyapunov condition. More generally, let $K = \{q: b(q) > 0\}$, then in words, the above assumption ensures a negative drift proportional to $V(q)$ outside $K$. On the other hand, inside $K$, our drift might be positive but it is controlled by the $b(q)$ for $q \in K$. If $K$ is a singleton then we have a slightly modified assumption as follows.

\begin{assumption}
\label{assumption: foster-lyapunov-singleton}
There exists a single point $x^* \in \cS$, a Lyapunov function $V: \cS \rightarrow [0,\infty)$ satisfying $V(q) > 0 \, \forall q \neq x^*$ and constants $\gamma, B > 0$ such that
\begin{align}
    \label{eqn: foster-lyapunov-singleton}
    \cL V(q) \leq - \gamma V(q) + B 1_{\{x^*\}} \, \forall q \in \cS.
\end{align}
\end{assumption}

% \textcolor{red}{Cite Sean Meyn singleton paper. This result follows from ... and we present the proof of this in ... for completeness. We immediately obtain the Poincar\'e constant using Proposition}

Unlike Assumption \ref{assumption: foster-lyapunov}, Assumption \ref{assumption: foster-lyapunov-singleton} allows us to have $V(x^*) < 1$. In many settings to be discussed below, this modification is necessary to obtain the tight mixing rate in the case we have a negative drift outside of a singleton. From here, we have the following proposition.

\begin{prop}
    \label{prop: lyapunov-poincare-singleton}
    Assume that Assumptions \ref{assumption: ctmc} and \ref{assumption: foster-lyapunov-singleton} holds where $\{b(q) > 0\} \subseteq \cS$ is a singleton, then the CTMC admits the Poincar\'e constant $C_P = \frac{1}{\gamma}$.
\end{prop}

While a similar convergence result for TV distance was previously established \cite{Lund1996-computable-rate-stochastically-ordered}, this result allows us to establish Chi-square convergence, and we present the proof in Appendix \ref{sssec: singleton-poincare-constant-proof}. 
% \st{Note that a similar result is presented in} \cite{Lund1996-computable-rate-stochastically-ordered} \st{and we present the proof of this result in Appendix \ref{sssec: singleton-poincare-constant-proof}}
Combining the above result with Proposition \ref{prop: poincare-equals-mixing}, one can obtain the Chi-square convergence as in \eqref{eqn:chi-square-convergence}. More generally, the finite set $K$ may not be a singleton for most of the queueing systems (including the $M/M/n$ queue), and thus, the Foster-Lyapunov assumption alone fails to provide a Poincar\'e inequality since we do not know how the system would mix inside $K$. So we need to establish a local mixing result inside $K$, which can be done using a local Poincar\'e inequality. Such a result is formalized in the following assumption.

% \textcolor{red}{However, for a Markov chain, we can only get a drift outside of a finite set. Thus, we need to establish some local mixing results, which is done by obtaining a local Poincar\'e inequality as follows.}

\begin{assumption}
\label{assumption: weighted-poincare} 
(Weighted Poincar\'e) Given the stationary distribution $\nu$, a function $b: \cS \rightarrow [0,\infty)$ such that $\sum_{q \in \cS} b(q)\nu(q)$ is finite and let $\tau(q) = \frac{b(q) \nu(q)}{\sum_{q \in \cS} b(q)\nu(q)} \forall q \in \cS$ be a $(b,\nu)$-weighted distribution. Denote $K = \{q \in \cS: b(q) > 0\}$, a CTMC is said to admit a $b$-weighted Poincar\'e inequality if there exists a non-negative constant $C_b$ such that
\begin{align}
    \label{eqn: weighted-poincare}
    \Var_\tau(f) = \norm{f - \E_\tau[f]}_{2,\tau}^2 \leq \frac{C_b}{\nu(K)} \langle f, -\cL f \rangle_\nu \, \forall f \in \ell_{2, \nu}.
\end{align}
