        \Var_\nu(f) \leq \frac{1 + \br{\sum_{q \in \cS} b(q) \nu_K(q)} C_b}{\gamma} \langle f, -\cL f \rangle_\nu \, \forall f \in \ell_{2,\nu},
    \end{align}
    where $C_b$ is the weighted local Poincar\'e constant in Assumption \ref{assumption: weighted-poincare}, $\nu$ is the stationary distribution of the CTMC and $b: \cS \rightarrow [0,\infty)$ is the positive drift term in Assumption \ref{assumption: foster-lyapunov}.
\end{theorem}

