Here, $C_L$ can also be understood as the congestion ratio, which is lower bounded by the inverse mixing rate \cite{Levin2017-mixing-book}. When $\nu_K$ is roughly uniform and the transitions are roughly symmetric, the constant $C_L$ is proportion to the sum of the path length of the path passes through an edge $e = (k,k+1)$ that maximizes the constant. As the name suggests, we prove this lemma by analyzing the path structure as follows.

\begin{proof}
    We emulate the proof for the canonical path method as in \cite{UBCmixingbook} to handle the continuous-time Markov chain. Denote $\gamma_{x,y}$ as one of the paths connecting $x,y$, note that $\cL(x,y) > 0$ if and only if $|x-y| = 1$, thus all path in $K$ is a sequence of adjacent states. For any test function $f \in \ell_{2, \nu_K}$ and let $Q_K(x,y) = \nu_K(x)\cL(x,y) \forall x \neq y$, we have:
    \begin{align*}
        \Var_{\nu_K}(f) &= \sum_{x < y \in K} \nu_K(x)\nu_K(y) \br{f(x)-f(y)}^2\\
        &\overset{(a)}{\leq} \sum_{x < y \in K} |x-y| \nu_K(x)\nu_K(y) \br{\sum_{x \leq k \leq y-1} (f(k)-f(k+1))^2} \\
        % \text{ by Cauchy-Schwarz inequality } \\
        &= \sum_{x < y \in K} |x-y| \nu_K(x)\nu_K(y) \br{\sum_{x \leq k \leq y-1} \frac{(f(k)-f(k+1))^2 Q_K(k,k+1)}{Q_K(k,k+1)}} \\
        &\overset{(b)}{\leq} \sum_{k: k,k+1 \in K} \br{\frac{ \sum_{x,y \in K: x \leq k \leq y-1} |x-y| \nu_K(x) \nu_K(y)}{Q_K(k,k+1)}} \br{f(k)-f(k+1)}^2 Q_K(k,k+1).
        % &\overset{(b)}{\leq} \sum_{k \geq 0} \br{\frac{ \sum_{x,y \in K: x \leq k \leq y-1} |x-y| \nu_K(x) \nu_K(y)}{Q_K(k,k+1)}} \br{f(k)-f(k+1)}^2 Q_K(k,k+1) \\
        % &\overset{(c)}{=} \frac{1}{\br{\sum_{x \in K} \nu(x)}^2}\sum_{k \geq 0} \br{\frac{ \sum_{x,y \in K: x \leq k \leq y-1} |x-y| \nu(x) \nu(y)}{Q(k,k+1)}} \br{f(k)-f(k+1)}^2 Q(k,k+1) \\
        % &\overset{(c)}{\leq} C_L \langle f, -\cL f\rangle_\nu.
    \end{align*}
    Here, (a) follows from Cauchy-Schwarz inequality and (b) follows from the interchange of sums. Hence proved.
    % , (b) follows from the fact that $Q(k,k+1) (f(k)-f(k+1))^2 \geq 0 \forall k \geq 0$ and the fact that we sum over all the states in $\Z_{\geq 0}$,
