\title{\LARGE \bf Observer-Based Distributed Model Predictive Control for String-Stable Multi-vehicle Systems with Markovian Switching Topology

\author{Wenwei Que$^{1}$, Yang Li$^{1}$, Lu Wang$^{1}$, Wentao Liu$^{1}$, Yougang Bian$^{1}$, Manjiang Hu$^{1}$, Yongfu Li$^{2}$}

