\subsection{Fully Distributed Adaptive Observer }\label{AA}
\par For every follower $i\in\mathbb{N}$, a fully distributed adaptive observer is designed as follows to directly get the leader's state or indirectly obtain this information from its  neighbors via V2V communication:
\begin{align}\label{eq:observer}
\begin{cases}\dot{\vartheta}_i(t)=A\vartheta_i(t)-\big(\varsigma_i(t)+\varrho_i(t)\big)\Psi_i(\varsigma_{i}(t))P\phi_i(t),\\\dot{\varrho}_i(t)=\phi_i^T(t)\Gamma\phi_i(t),\\\varsigma_i(t)=\phi_i^T(t)\Upsilon\phi_i(t),\end{cases}
\end{align}
where $\vartheta_{i}(t)\in\mathbb{R}^3$ is the state of observer $i$.  $ \varsigma_i(t), \varrho_i(t)\in\mathbb{R}^+$ indicate the adaptive coupling gains with $\varrho_{i}(0)\geq1$ and $\Psi_i(\cdot)$ is a nonlinear increasing non-negative function fulfilling $\Psi_i(\cdot)\geq1$ which will be designed later. Matrices $P$, $\Gamma$, and  $\Upsilon$ with the appropriate dimensions need to be designed. We define the observation error  $\theta_{i}(t) = \vartheta_{i}(t)- x_0 (t)=[\theta_{p,i},\theta_{v,i},\theta_{a,i}]^T$ and $x_0 (t)$ is the leader's state.  $\phi_i (t)$ is the relative observation error, defined as follows:
\begin{align}\label{eq:relative observation error}
\phi_{i}(t)=\sum_{j=1}^{N}m_{ij}(\sigma(t))\theta_{j}(t), 
\end{align}
where $m_{ij}(\sigma(t))$ is the element of $\mathcal{M}(\sigma(t))$. Denote $\kappa_i(t) = (\varsigma_i(t) + \varrho_i(t))\Psi_i(\varsigma_i(t))$. The update law of $\phi_{i}(t)$ gives
\begin{align}\label{eq:update of relative observation error}
\dot{\phi}_{i}(t)=&A\phi_{i}(t)-
\sum_{j=1}^{N}m_{ij}\kappa_j(t)P\phi_{j}(t).
\end{align}
% \begin{remark}
% Compared with \cite{wang2024cyber}, quadratic extra gain $\varsigma_i(t)$ is introduced to assist the derivation to adapt to the directed communication topology \cite{liu2024time}. Inspired by \cite{wang2022distributed}, an adaptive coupling gain $\Psi_i(\varsigma_{i}(t))$ is introduced to accelerate the convergence of observer states.  We constructed the Lyapunov function using  $\varsigma_i(t)$ and $\Psi_i(\varsigma_{i}(t))$, and provided a sufficient condition in Theorem \ref{thm: convergence of observer}. Based on the proof of Theorem \ref{thm: convergence of observer}, we note that the selection of  $\Psi_i(\varsigma_{i}(t))$ offers flexibility and can be determined experimentally.
% \end{remark}

\begin{theorem}
\label{thm: convergence of observer}
    Select coefficient matrix  $\Gamma=I_{n_0}$ and $\Upsilon=P^{-1}$ satisfying $\Gamma=\Upsilon P$, under Assumptions \ref{ass:continuous-time Markov process} and \ref{ass: a directed spanning tree rooted at the leader}, the fully distributed observer  \eqref{eq:observer}-\eqref{eq:update of relative observation error} can reach consensus in the mean square sense, i.e., $\lim_{t\to+\infty}\mathbb{E}[\theta_i(t)]=0$ and $\lim_{t\to+\infty}\mathbb{E}[\varrho_{i}(t)]=0$ for $i\in\{1,2,\cdotp\cdotp\cdotp,N\}$, if there exists a  positive-define solution $P$ that satisfies
\begin{align}\label{eq:theorem}
PA+A^{T}P-2P^{2}+\mathcal{Q}=0,
\end{align}
where the matrix $\mathcal{Q}$ is positive definite and $I_{n_0}$ stands for the $n_0\times n_0$ real identity matrix. $n_0$ is the appropriate dimension. \par For simplicity,  time $t$ and  Markov process $\sigma(t)$ will be omitted unless causing ambiguity.
\end{theorem}
\begin{proof}Consider the following candidate Lyapunov function for system \eqref{eq:observer}:
\begin{align}\label{eq:11}
    V=&\sum_{\varphi=1}^{\iota}V_{\varphi}=\sum_{\varphi=1}^{\iota}\mathbb{E}\left[{\left({\sum_{i=1}^{N}\frac{h_i}{2}(2\varrho_{i}+\varsigma_{i})\int^{\varsigma_{i}}_{0}\Psi_i(s)ds}\right.}\right.\nonumber\\
&\left.{\left.{\qquad\qquad\,+\frac{\lambda_{0}\pi_{\text{min}}}{4}\sum^{N}_{i=1}\tilde{\varrho}_i^2}\right)\times\textbf{1}_{\{\sigma(t)=\varphi\}}}\right],
\end{align}
% where
% \begin{align}\label{eq:12}
% \nonumber
% V_{\varphi}=\mathbb{E}\left[{\left({\sum_{i=1}^{N}\frac{h_i}{2}(2\varrho_{i}+\varsigma_{i})\int^{\varsigma_{i}}_{0}\Psi_i(s)ds}\right.}\right.\\
% \left.{\left.{+\frac{\lambda_{0}\pi_{\text{min}}}{4}\sum^{N}_{i=1}\tilde{\varrho}_i^2}\right)\textbf{1}_{\{\sigma(t)=\varphi\}}}\right]
% \end{align}
where $\textbf{1}_{\{\sigma(t)=\varphi\}}$ stands for the Dirac measure over the set $\{\sigma(t)=\varphi\}$. $h_i$ is a positive constant and $\hat{h}=\left[h_{1},h_{2},\cdots ,h_{N}\right]^T$ is a left-eigenvector associated with eigenvalue of matrix $\bar{\mathcal{M}}$. $\bar{\mathcal{M}}$ corresponds to the union graph $\bar{\mathcal{G}}$. Define $H\triangleq \text{diag}\left(h_{1},h_{2},\cdots,h_{N}\right)$, $\lambda_{0}\triangleq\frac{\lambda_{2}\left(H\bar{\mathcal{M}}+\bar{\mathcal{M}}^{T}H\right)}{N}$, $\lambda_{2}(\cdot)$ represents the smallest nonzero eigenvalue of the matrix. $ \pi_{\text{min}}\triangleq \text{min}^{\iota}_{\varphi=1}\pi_\varphi$ and $\tilde{\varrho_i}=\varrho_i-\alpha$, where parameter $\alpha$ is a positive constant to be determined later. The function $V_\varphi$ is positive definite, and it follows from Lemma 3.6 in \cite{do2012continuous} that 
\begin{align}\label{eq:14}
\nonumber
dV_{\varphi}=&\mathbb{E}\left[\sum^{N}_{i=1}\frac{h_i}{2}\left(2\dot{\varrho}_{i}+\dot{\varsigma}_{i}\right)\int^{\varsigma_{i}}_{0}\Psi_i(s)ds \times\textbf{1}_{\{\sigma(t)=\varphi\}}\right]dt\\\nonumber&+\mathbb{E}\left[\sum^{N}_{i=1}\frac{h_i}{2}\left(2\varrho_{i}+\varsigma_{i}\right)\Psi_i\dot{\varsigma}_{i}  \times\textbf{1}_{\{\sigma(t)=\varphi\}}\right]dt\\\nonumber&+\mathbb{E}\left[\frac{\lambda_0\pi_{\text{min}}}{2}\sum^{N}_{i=1}\tilde{\varrho}_i\dot{\varrho}_i \times\textbf{1}_{\{\sigma(t)=\varphi\}}\right]dt\\&+\sum^\iota_{q=1}\mu_{q\varphi}V_{q}dt+o(dt).
\end{align}
\par Considering the fact that $\mu\cdot\textbf{1}=\textbf{0}$, the derivative of $V$ can be expressed as $\dot{V}=\sum^\iota_{\varphi=1}\dot{V}_\varphi$.
\par For $i\in\mathbb{N}$, the monotonically increasing functions $\Psi_i$ fulfill $\Psi_i(s)\geq1$ and $s>0$, using the mean value theorem for integrals, one can obtain that
\begin{align}\label{eq:15}
\nonumber
&\quad\mathbb{E}\left[\sum^{N}_{i=1}\frac{h_i}{2}\left(2\dot{\varrho}_{i}+\dot{\varsigma}_{i}\right)\int^{\varsigma_{i}}_{0}\Psi_i(s)ds \,\textbf{1}_{\{\sigma(t)=\varphi\}}\right]\\&\leq\mathbb{E}\left[\sum^N_{i=1}h_i\varsigma_i\Psi_i\phi_i^T\Gamma\phi_i\,\textbf{1}_{\{\sigma(t)=\varphi\}}\right]\nonumber\\&\quad
+\mathbb{E}\left[\sum^N_{i=1}\frac{h_i}{2}\dot{\varsigma_i}\varsigma_i\Psi_i\,\textbf{1}_{\{\sigma(t)=\varphi\}}\right].
\end{align}

  \par Using \eqref{eq:15} and \eqref{eq:update of relative observation error} yields
    \begin{align}\label{eq:16}
  \nonumber
\dot{V}&\leq\sum^\iota_{\varphi=1}\mathbb{E}\left[\sum^N_{i=1}h_i\varsigma_i\Psi_i\phi_i^T\Gamma\phi_i\,\textbf{1}_{\{\sigma(t)=\varphi\}}\right]\nonumber
\\&\quad+\sum^\iota_{\varphi=1}\mathbb{E}\left[\sum^N_{i=1}2h_i(\varrho_i+\varsigma_i)\Psi_i\phi_i^T\Upsilon A\phi_i\,\textbf{1}_{\{\sigma(t)=\varphi\}}\right]\nonumber
\\&\quad-\sum^\iota_{\varphi=1}\mathbb{E}\Bigg[2h_i(\varrho_i+\varsigma_i)\Psi_i\phi_i^T\Upsilon\nonumber
\\&\quad\times\bigg(\sum^N_{j=1}m_{ij}\kappa_j(t)P\phi_j\bigg)\,\textbf{1}_{\{\sigma(t)=\varphi\}}\Bigg]\nonumber
\\&\quad+\sum^\iota_{\varphi=1}\mathbb{E}\left[\frac{\lambda_0\pi_\text{min}}{2}\sum^N_{i=1}\tilde{\varrho}_i\phi_i^T\Gamma\phi_i\,\textbf{1}_{\{\sigma(t)=\varphi\}}\right].
  \end{align}
\par Given that $\sigma(t)$ has a unique distribution equal to $\pi$, by Lemma 1 from \cite{wang2022distributed}, it follows that 
\begin{align}\label{eq:17}
\nonumber
&\sum^\iota_{\varphi=1}\mathbb{E}\Bigg[2h_i(\varrho_i+\varsigma_i)\Psi_i\phi_i^T\Upsilon \sum^N_{j=1}m_{ij}\kappa_j(t)P\phi_j\,\textbf{1}_{\{\sigma(t)=\varphi\}}\Bigg]\nonumber
 \\\geq&\lambda_0\pi_{\text{min}}\mathbb{E}\left[\Phi^T\left(\Omega^2G^2\right)\otimes\left(\Upsilon P\right)\Phi\right],
\end{align}
 where diagonal matrix $\Omega=\text{diag}\left(\varrho_1+\varsigma_1,\cdots,\varrho_N+\varsigma_N\right)$ and $G=\text{diag}\left(\Psi_1,\cdots,\Psi_N\right)$, and $\Phi=[\phi_1,\cdots,\phi_N]^T$. $\otimes$ means Kronecker product.
If $\Gamma=\Upsilon P$ is true, then substituting \eqref{eq:17} into \eqref{eq:16} and using the Young's inequality, one has
\begin{align}\label{eq:18}
  \nonumber
\dot{V}&\leq\mathbb{E}\Bigg[\sum^N_{i=1}h_i(\varrho_i+\varsigma_i)\Psi_i\phi_i^T\left(\Upsilon A+A^T\Upsilon\right)\phi_i\Bigg]\nonumber
\\&\quad-\lambda_0\pi_{\text{min}}\mathbb{E}\left[\sum^N_{i=1}\left(\left(\varrho+\varsigma\right)^2\Psi_i^2-\frac{\varrho_i}{2}-\frac{\varsigma_i^2}{2}\Psi_i^2\right)\phi_i^T\Gamma\phi_i\right]\nonumber
\\&\quad-\mathbb{E}\Bigg[\sum^N_{i=1}\left(\frac{\lambda_0\pi_{\text{min}}}{2}\alpha-\frac{h_i^2}{2\lambda_0\pi_{\text{min}}}\right)\phi_i^T\Gamma\phi_i\Bigg].
 \end{align}
