%   \nonumber
% \dot{V}&\leq\sum^\iota_{\varphi=1}\mathbb{E}\left[\sum^N_{i=1}h_i\varsigma_i\Psi_i\phi_i^T\Gamma\phi_i\,\textbf{1}_{\{\sigma(t)=\varphi\}}\right]\nonumber
% \\&\quad+\sum^\iota_{\varphi=1}\mathbb{E}\Bigg[\sum^N_{i=1}h_i\Psi_i(\varrho_i+\varsigma_i)\phi_i^T\left(\Upsilon A_0+A_0^T\Upsilon\right)\nonumber
% \\&\quad\times\phi_i\,\textbf{1}_{\{\sigma(t)=\varphi\}}\Bigg]\nonumber
% \\&\quad-\lambda_0\pi_{\text{min}}\mathbb{E}\left[\sum^N_{i=1}\left(\varrho+\varsigma\right)^2\Psi_i^2\phi_i^T\Upsilon P\phi_i\right]\nonumber
% \\&\quad+\sum^\iota_{\varphi=1}\mathbb{E}\left[\frac{\lambda_0\pi_\text{min}}{2}\sum^N_{i=1}\tilde{\varrho}_i\phi_i^T\Gamma\phi_i\,\textbf{1}_{\{\sigma(t)=\varphi\}}\right]\nonumber
% \\&\leq\sum^l_{\varphi=1}\mathbb{E}\Bigg[\sum^N_{i=1}h_i\Psi_i(\varrho_i+\varsigma_i)\phi_i^T\left(\Upsilon A_0+A_0^T\Upsilon\right)\nonumber
% \\&\quad\times\phi_i\,\textbf{1}_{\{\sigma(t)=\varphi\}}\Bigg]\nonumber
% \\&\quad-\lambda_0\pi_{\text{min}}\mathbb{E}\left[\sum^N_{i=1}\left(\left(\varrho+\varsigma\right)^2\Psi_i^2-\frac{\varrho_i}{2}-\frac{\varsigma_i^2}{2}\Psi_i^2\right)\phi_i^T\Gamma\phi_i\right]\nonumber
% \\&\quad-\mathbb{E}\Bigg[\sum^N_{i=1}\left(\frac{\lambda_0\pi_{\text{min}}}{2}\alpha-\frac{h_i^2}{2\lambda_0\pi_{\text{min}}}\right)\phi_i^T\Gamma\phi_i\Bigg]
%  \end{align}
\par Noting that $\Psi_i\geq1$ and $\varrho_{i}\geq1$, one has
\begin{align}\label{eq:19}
\frac{\varrho_i}{2}+\frac{\varsigma_i^2}{2}\Psi_i^2\leq(\frac{\varrho_i^2}{2}+\frac{\varsigma_i^2}{2}+\varrho_i\varsigma_i)\Psi_i^2=\frac{1}{2}(\varrho_i+\varsigma_i)^2\Psi_i^2.
 \end{align}
 \par Let $\alpha\geq\hat{\alpha}+\text{max}_{i=1}^N\frac{h_i^2}{(\lambda_0\pi_{\text{min}})^2}$, $\hat{\alpha}$ will be determined later. Substituting \eqref{eq:19} into \eqref{eq:18}, it follows that
 \begin{align}\label{ea:20}
\dot{V}&\leq\mathbb{E}\Bigg[\sum^N_{i=1}h_i(\varrho_i+\varsigma_i)\Psi_i\phi_i^T\left(\Upsilon A+A^T\Upsilon\right)\phi_i\Bigg]\nonumber
\\&\quad-\frac{\lambda_0\pi_{\text{min}}}{2}\mathbb{E}\left[\sum^N_{i=1}\left(\left(\varrho_i+\varsigma_i\right)^2\Psi_i^2+\hat{\alpha}\right)\phi_i^T\Gamma\phi_i\right].
 \end{align}
 \par Using the Young's inequality and selecting $\hat{\alpha}$ satisfying $\sqrt{\hat{\alpha}}\lambda_0\pi_{\text{min}}\geq2\text{max}^N_{i=1}h_i$, one has
 \begin{align}\label{eq:21}
&\quad\frac{\lambda_0\pi_{\text{min}}}{2}\mathbb{E}\left[\sum^N_{i=1}\left(\left(\varrho_i+\varsigma_i\right)^2\Psi_i^2+\hat{\alpha}\right)\phi_i^T\Gamma\phi_i\right]\nonumber
\\&\geq\lambda_0\pi_{\text{min}}\mathbb{E}\left[\sum^N_{i=1}\sqrt{\hat{\alpha}}\left(\varrho_i+\varsigma_i\right)\Psi_i\phi_i^T\Gamma\phi_i\right]\nonumber
\\&\geq\mathbb{E}\left[2\sum^N_{i=1}h_i\left(\varrho_i+\varsigma_i\right)\Psi_i\phi_i^T\Gamma\phi_i\right].
 \end{align}
 \par Let $\bar{\Phi}=\left(\sqrt{\Omega GH}\otimes I_{n_0}\right)\Phi$, then substituting \eqref{eq:21} into \eqref{ea:20} gives  
 \begin{align}\label{eq:22}
\dot{V}\leq\mathbb{E}\left[\bar{\Phi}^T\left(I_N\otimes\left(\Upsilon A+A^T\Upsilon-2\Gamma\right)\right)\bar{\Phi}\right].
 \end{align}
\par Choose  $\Gamma=I_{n_0}$ and $\Upsilon=P^{-1}$ and consider that
\begin{align}\label{eq:23}
P^{-1}A+A^TP^{-1}-2I_{n_0}<0,
\end{align}
where the inequality \eqref{eq:theorem} is derived by multiplying both sides of \eqref{eq:23} by $P$, it follows that
\begin{align}\label{eq:24}
\dot{V}\leq-\lambda_{\text{min}}\mathbb{E}\left[\|\Phi\|^2\right]\leq0,
\end{align}
 where let $\lambda_{\text{min}}$ be the smallest eigenvalue of the matrix $-\left(\Omega GH\otimes\left(P^{-1}A+A^TP^{-1}-2I_{n_0}\right)\right)$. Hence, the Lyapunov function $V$ is bounded. 
 \par Assume that $\lim_{t\to+\infty}\mathbb{E}\left[\|\Phi\|^2\right]=\xi$ and $\xi>0$, there exists a time instant $t^*$ such that $\mathbb{E}\left[\|\Phi\|^2\right]>\frac{\xi}{2}$ when $t\geq t^*$.
 \par By integrating \eqref{eq:25} from $t^*=0$ to $t=+\infty$, we can obtain that
 \begin{align}\label{eq:25}
+\infty=\int^{+\infty}_{t^*}\frac{\xi}{2}dt&<\int^{+\infty}_{t^*}\mathbb{E}\left[\|\Phi\|^2\right]dt\nonumber\\&<\frac{1}{\lambda_{\text{min}}}\left(V\left(t^*\right)-V\left(+\infty\right)\right)=-\infty.
 \end{align}
 \par This provides a contradiction-based proof. Thus $\xi=0$, then we can obtain $\lim_{t\to+\infty}\mathbb{E}\left[\|\Phi\|^2\right]=0$. Furthermore, considering Jensen’s
inequality, one has $\mathbb{E}\left[\|\Phi^2\|\right]\geq\left(\mathbb{E}\left[\|\Phi\|\right]\right)^2$. Then we can derive $\lim_{t\to+\infty}\mathbb{E}\left[\|\Phi\|\right]=0$. Considering \eqref{eq:relative observation error}, it is obtained that $\lim_{t\to+\infty}\mathbb{E}\left[\theta_i\right]=0$ and $\lim_{t\to+\infty}\mathbb{E}\left[\varrho_i\right]=0$. Therefore, the observer states in \eqref{eq:observer} can achieve consensus in the mean square sense. The proof is completed.
% , i.e.,
% \begin{align}\label{eq:26}
% \begin{cases}
% \lim_{t\to+\infty}\mathbb{E}\left[\|\hat{p}_i(t)-p_0(t)\|^2\right]=0\\\lim_{t\to+\infty}\mathbb{E}\left[\|\hat{v}_i(t)-v_0(t)\|^2\right]=0\\\lim_{t\to+\infty}\mathbb{E}\left[\|\hat{a}_i(t)-a_0(t)\|^2\right]=0
% \end{cases}
% \end{align}
\end{proof}
\begin{remark}
Compared with \cite{wang2024cyber}, quadratic extra gain $\varsigma_i(t)$ is introduced to assist the derivation to adapt to the directed communication topology \cite{liu2024time}. Inspired by \cite{wang2022distributed}, an adaptive coupling gain $\Psi_i(\varsigma_{i}(t))$ is introduced to accelerate the convergence of observer states.  We constructed the Lyapunov function \eqref{eq:11} using  $\varsigma_i(t)$ and $\Psi_i(\varsigma_{i}(t))$, and provided a sufficient condition \eqref{eq:theorem} in Theorem \ref{thm: convergence of observer}. Based on the proof of Theorem \ref{thm: convergence of observer}, we note that the selection of  $\Psi_i(\varsigma_{i}(t))$ offers flexibility and can be determined experimentally.
\end{remark}
\subsection{Distributed Model Predictive Control Algorithm}
\par To model the DMPC framework (see Fig.  \ref{fig:principle_scheme}), the Euler method is used to discretize system dynamics \eqref{eq:continuous linear follower model} and \eqref{eq:continuous leader model} with sampling time $\Delta t$ as follows, which is also used in \cite{wang2025string}:
 \begin{align}
&x_i(k+1)=A_dx_i(k)+B_du_i(k),\nonumber\\
     &A_d=\begin{bmatrix}1&\Delta t&0\\0&1&\Delta t\\0&0&1\end{bmatrix},B_d=\begin{bmatrix}0\\0\\\Delta t\end{bmatrix},\label{eq:discrete follower model}\\
     &x_0(k+1)=A_dx_0(k).\label{eq:discrete leader model}
 \end{align}
%  \begin{align}\label{eq:discrete leader model}
%      &x_0(k+1)=A_dx_0(k).
% \end{align}
\par The control strategy for the DMPC framework is shown in Fig. \ref{fig:principle_scheme}. At time $t$, vehicle $i$ obtains the assumed trajectories of its predecessor and the assumed observation trajectories (generated by \eqref{eq:discrete leader model}) of its in-neighbors, and then uses this information, along with its own assumed trajectory and assumed observation trajectory, to solve the optimal control problem. The first control input from the optimal solution is applied to control vehicle $i$ at time $t$, while the remaining control inputs are combined with the updated terminal control input to generate the assumed trajectory for time $t+1$.  $N_p$ is the predictive horizon. For arbitrary integers $N_1$, $N_2$ satisfying $N_1<N_2$, define $\mathbb{K}_{N_1:N_2}=\{N_1,N_1+1,\cdots,N_2-1,N_2\}$. We denote $\mathbb{K}_{0:N_p-1}=\mathbb{K}_1$ and $\mathbb{K}_{0:N_p}=\mathbb{K}_2$. Three types of state trajectories and control input trajectories are defined as follows:
\par i) The predicted trajectory $x_i^p(k|t),k\in\mathbb{K}_{2}$ and $u_i^p(k|t),k\in\mathbb{K}_{1}$, the variables to be optimized; 
\par ii) The optimal trajectory $x_i^*(k|t),k\in\mathbb{K}_{2}$ and $u_i^*(k|t),k\in\mathbb{K}_{1}$, the optimal solution of the local optimization problem; 
\par iii) The assumed trajectory $x_i^a(k|t),k\in\mathbb{K}_{2}$ and $u_i^a(k|t),k\in\mathbb{K}_{1}$, the parameters generated with the optimal trajectories.
\par Additionally, we denote by $\vartheta_i^a(k|t),k\in\mathbb{K}_{2}$ the assumed observation trajectory. Based on the observation of the leader, we can design an optimization problem $\mathcal{P}_i(t)$ for vehicle $i$ at time $t$ as follows:
\begin{subequations}
\begin{align}
&\min_{u_i^p(k|t),k\in\mathbb{K}_{1}}J_i\left(x_i^p,u_i^p,x_i^a,\vartheta_i^a,\vartheta_j^a,x_{i-1}^a;\mathbb{K}_{1}|t\right)\nonumber\\
&=\sum_{k=0}^{N_p-1}l_i\left(x_i^p,u_i^p,x_i^a,\vartheta_i^a,\vartheta_j^a,x_{i-1}^a;k|t\right)\label{eq:28a}\\
\
&s.t.\qquad x_i^p(0|t)=x_i(t),\label{eq:28b}\\
&x_i^p(k+1|t)=A_dx_i^p(k|t)+B_du_i^p(k|t),k\in\mathbb{K}_{1},\label{eq:28c}\\
&\qquad u_i^p(k|t)\in\mathbb{U}_i,k\in\mathbb{K}_{1},\label{eq:28d}\\
&\qquad x_i^p(N_p|t)=x_i^a(N_p|t),\label{eq:28e}\\
&\qquad\left\|\gamma\hat{e}_i^p(k|t)\right\|_{\infty} \leq \beta_{i}D_{i-1}(t),k\in\mathbb{K}_{2},\label{eq:28f}
\end{align}
\end{subequations}
where $\mathbb{U}_i$ is the control input set. \eqref{eq:28b}, \eqref{eq:28c}, and \eqref{eq:28d} represent the constraint of the initial state, vehicle dynamics, and control input, respectively.  \eqref{eq:28e} is the terminal state constraint and \eqref{eq:28f} is the observer-based string stable constraint.
\par In constraint \eqref{eq:28f},  $\gamma=[1,0,0]$. To obtain more accurate observations of the leader, we define the average observation as $\vartheta_{i,avg}(t)=\frac{1}{|\mathbb{I}_i(\sigma(t))|+1}\left[\vartheta_i(t)+\sum_{j\in\mathbb{I}_i(\sigma(t))}\vartheta_j(t)\right]$, 
% \begin{align}\label{eq: average observation}
% \hat{x}_{i,avg}(t)=\frac{1}{|\mathbb{I}_i|+1}\left[\hat{x}_i(t)+\sum_{j\in\mathbb{I}_i}\hat{x}_j(t)\right]
% \end{align}
where $|\mathbb{I}_i(\sigma(t))|$ is cardinality of $\mathbb{I}_i(\sigma(t))$. We denote  $\hat{e}_i(t)=x_i(t)-\vartheta_{i,avg}(t)+\tilde{d}_{i0}$. Then we define $D_{i-1}=\text{max}\left\{\|\gamma \hat{e}_{i-1}(\tau)\|_\infty, \|\gamma \hat{e}^a_{i-1}(k|t)\|_\infty\right\}$, 
where $\|\gamma \hat{e}_{i-1}(\tau)\|_\infty=\text{max}_{0<\tau\leq t}|\gamma \hat{e}_{i-1}(\tau)|$ represents the max spacing error of preceding vehicle $i-1$ in the historical trajectory and $\|\gamma \hat{e}_{i-1}^a(k|t)\|_\infty=\text{max}_{k\in\mathbb{K}_2}|\gamma \hat{e}_{i-1}^a(k|t)|$ represents the max spacing error of preceding vehicle $i-1$ in the assumed trajectory. The cost function is defined as:
\begin{align}\label{eq:cost}
  & l_i(x_i^p,u_i^p,x_i^a,\vartheta_i^a,\vartheta_j^a,x_{i-1}^a;k|t)\nonumber\\
=&\left\|u_i^p(k|t)\right\|_{R_i}+\left\|x_i^p(k|t)-x_i^a(k|t)\right\|_{F_i}\nonumber\\
  & +\left\|x_i^p(k|t)-x_{i-1}^a(k|t)+\tilde{d}_0\right\|_{S_i}\nonumber\\
  &+\left\|x_i^p(k|t)-\vartheta_{i,avg}^a(k|t)+\tilde{d}_{i0}\right\|_{G_i},
\end{align}
where $R_i$, $F_i$, $S_i$, and $G_i$ are positive definite diagonal matrices, representing the weight of the corresponding penalty term. $\left\|u_i^p(k|t)\right\|_{R_i}$ is the penalty for the control input; $\left\|x_i^p(k|t)-x_i^a(k|t)\right\|_{F_i}$ is the penalty for the deviation between the predicted and assumed states of vehicle $i$; $\left\|x_i^p(k|t)-x_{i-1}^a(k|t)+\tilde{d}_0\right\|_{S_i}$ is the penalty for the deviation between vehicle $i$'s predicted states and the preceding vehicle $i-1$'s assumed states with offset $\tilde{d}_0=[d_0,0,0]^T$. When $i=1$, the preceding vehicle is the leader; $\left\|x_i^p(k|t)-\vartheta_{i,avg}^a(k|t)+\tilde{d}_{i0}\right\|_{G_i}$ is the penalty for the deviation between vehicle $i$'s predicted states and average observation states with offset $\tilde{d}_{i0}$. Here we denote by $\vartheta_{i,avg}^a(k|t),k\in\mathbb{K}_{2}$ the average assumed observation trajectory.
\par From \eqref{eq:28f}, we derive $x_i^*(N_p|t)=x_i^a(N_p|t)$. The update law is formulated as:
\begin{align}\label{eq:terminal state update}
x_i^a(N_p|t+1)=A_dx_i^a(N_p|t)+B_du^*_i(N_p|t),
\end{align}
where $x_i^a(N_p|t+1)$ represents the assumed state of $N_p$ at time $t+1$ looking forward and $u_i^*(N_p|t)=K\cdotp\left(\vartheta_{i,avg}^a(N_p|t)-x_i^a(N_p|t)-\tilde{d}_{i0}\right)$. We note that $u_i^*(N_p|t)$ is defined only for notational simplicity, and the control gain matrix $K$ can be determined by the modified algebraic Riccati equation in \cite{bian2020distributed}.



