\subsection{Case Study: Multirotors Transporting a Payload (MP)}

\subsubsection{Constrained Dynamics}

%
The dynamics of multirotors with cable-suspended payloads, as presented in~\cite{wahba2024kinodynamic}, are described using the minimal state representation
\begin{equation}
    \label{eq:statespace}
    \x_m = (\po, \vo, \scfirst, \wifirst, \mathbf{R}^1, \wuavfirst, \ldots, \scn, \win, \mathbf{R}^N, \wuavn)^\top,
\end{equation} 
where $\mathbf{p}^0\in \mathbb{R}^3$ is the payload's position, $\vo \in \mathbb{R}^3$ is the payload velocity, $\sci \in \mathbb{S}^2$ are the cable unit vectors pointing from the UAV to the payload (with $\mathbb{S}^2 = \{\mathbf{s} \in \mathbb{R}^3 \big| \|\mathbf{s}\| = 1\}$), and $\boldsymbol{\omega}^i \in \mathbb{R}^3$ are the cable angular velocities, where $i \in \{1, \ldots, N\}$. 
%

The UAV position and velocity vectors are $\p^i\in \mathbb{R}^3$ and $\dot{\p}^i \in \mathbb{R}^3$ are computed as 
\begin{equation}
    \label{eq:uavpos}
    \p^i = \po - l^i\sci, \quad \dot\p^i = \dot \p^0 - l^i \scidot.
\end{equation}

The dynamics $\mathbf{f}_m$ of the system is defined as
\begin{align}
    \label{eq:mpdynamics}
    &\scidot = \wi \times \sci, \quad \sci = \frac{\p^0 - \p^i}{\|\p^0 - \p^i\|},\\
    &\mathbf{M_{t}}(\podd +g\ez)  = \sum_{i=1}^n (f_{T}^i\R^i\ez - m^i l^i\|\wi\|^2\sci), \nonumber\\
    &m^i l^i\dot{\boldsymbol{\omega}}^i = m^i \scihat(\podd +g\ez) - f^i_{T}\scihat\R^i\ez, \nonumber\\
    &\dot{\mathbf{R}}^i = \mathbf{R}^i \hat{\wuav}^i,
    \quad \mathbf{J} \wdot^i = \mathbf{J} \wuav^i \times \wuav^i + \mathbf{M}^i, \nonumber
\end{align}
where $\podd$ is the payload acceleration, $\mathbf{M}_{t} = m^0 \mathbf{I}_{3} + \sum_{i=1}^n m^i \sci{\sci}^\top$ and $g$ is the gravitational acceleration.

\subsubsection{Conflicts}
\input{tables/table_sim1}

A challenge for the conflict detection is that the constraint $\mathbf{g}(\x)$ depends on the payload position $\p^0$, which is not part of the stacked state.
Thus, we estimate the payload positions $\poest_k$ by solving the following optimization problem
\begin{align}
    \label{eq:payload-optimization}
    \min_{\poest_k} \sum_{i=1}^{N} &(\|\poest_k - \mathbf{p}_k^i\| - l^i)^2 + 
    \mu \|\poest_k - \p^{0_d}_{k}\| \\ & +  
    \lambda (\min_{i}\{p_{z_k}^i\} - p^{0_e}_{z_k} - l_{\text{min}})^2,    \nonumber
\end{align}
where $\mu$ and $\lambda$ are weighting parameters, $\p^{0_d}_{k}$ is used to penalize jumps of the payload estimate from the previous solution, and $l_{\text{min}}$ is the cable length associated with the robot closest to the payload $\min_{i}\{p_{z_k}^i\}$ in the $z$-axis among all robots. 
This cost function ensures that the payload position minimizes deviations from nominal cable lengths, penalizes significant changes in the payload position, and guarantees the estimated payload position remains below the robots' positions.

Once the payload position $\poest_k$ is estimated, the actual cable lengths are computed as
\begin{equation}
    \lcki = \|\poest_k - \mathbf{p}_k^i\|, \quad \forall i \in \{1, \dots, N\}.
\end{equation}
A conflict in the second level for all robots arises if any cable length $\lcki$ deviates from the nominal cable length $l^i$ by more than the tolerance $\delta$
\begin{equation}
    | \lcki - l^i | > \delta.
\end{equation}
Note that in this case all robots participate in the conflict.

