\section{Proofs}\label{app:proofs} 

\textbf{Proposition \ref{prop}} \our does not suffer from the automorphic node problem.
\begin{proof}
According to Proposition~\ref{prop:auto}, a model $M$ suffers from the \emph{automorphic node problem} if, for any graph $G=(V,E,\mathbf{X}^0)$, for any pairs of links \((u,v), (u',v') \in V \times V\), for any $F\in M$ it holds that:
\[
(u,v) \not\simeq (u',v'), \quad u \simeq u', \quad v \simeq v', \quad \text{and} \quad F((u,v), G) \neq F((u',v'), G).
\]

In order to prove that \our{} does not suffer from the automorphic node problem, it suffices to provide an example of a graph \(G = (V, E, X^0)\) and node pairs \((u,v), (u',v') \in V \times V\) such that:
\[
(u,v) \not\simeq (u',v'), \quad u \simeq u', \quad v \simeq v', \quad \text{and} \quad \our((u,v), G) \neq \our((u',v'), G).
\]

Such an example is provided in Figure~\ref{fig:fail}: the shortest path from $v$ to $u'$ consists of $v$, an orange node, and $u'$, whereas the shortest path from $v$ to $u$ includes $v$, an orange node, a yellow node, another orange node, and finally $u$. Thus, simply using a summation as function $\phi$, leads to distinct representations for links $(v,u)$ and $(v,u')$.

\end{proof}

\textbf{Theorem \ref{thm}}  \our is strictly more expressive than Pure GNN, NCN, BUDDY, NBFnet and Neo-GNN.
\begin{proof} We proceed by prove each comparison separately.
\begin{itemize}
    \item \underline{\our is strictly more expressive than Pure GNN.}

We prove this by noting that \our architecture (Equation~\ref{eq:our}) generalizes that of pure GNNs, meaning that \our can simulate any pure GNN by simply ignoring the shortest path information. Thus, for any pair of non-automorphic links that a specific pure GNN can distinguish, there exists a configuration of \our that distinguishes them as well. We can conclude that \our is strictly more expressive than pure GNNs considering as example of pair of links indistinguishable by GNNs but distinguishable by \our the one provided is provided in the proof of Proposition~\ref{prop}.

\item \underline{\our is strictly more expressive than NCN.}


We prove this in two steps:  
(1) When two links share no common neighbors, NCN on them reduces to a pure GNN. As we have already proved that \our is strictly more expressive than pure GNNs, it follows that \our is also strictly more expressive than NCN in this case. (2) When the links have common neighbors, setting $\text{AGG}$ as summation, $\rho$ as the Hadamard product between the endpoint representations and the concatenation with the result of the aggregation, and $\phi$ as the identity function, \our reduces exactly to NCN. Therefore, if NCN can distinguish two links under some configuration, \our can as well. By definition~\ref{moreex}), this implies that \our is more expressive than NCN. We can conclude that \our is strictly more expressive than NCN considering the example in Figure~\ref{fig:reg}. The graph is regular and thus all nodes receive the same embedding from a GNN. Consider nodes $u$ and $v$: $N(u) \cap N(v) = N(u) \cap N(v') = \emptyset$. In this case, NCN reduces to a pure GNN and is thus unable to distinguish the links $(u,v)$ and $(u',v')$. Now, let $\mathbf{x} \in \mathbb{R}^d$ be the representation assigned to every node by a GNN. Then, the representation of the shortest path $\mathcal{P}^*_G(u,v)$ is simply $(\mathbf{x}, \mathbf{x}, \mathbf{x})$, while $\mathcal{P}^*_G(u',v') = (\mathbf{x}, \mathbf{x}, \mathbf{x}, \mathbf{x})$. Even using a simple sum as aggregation function, \our successfully distinguishes between the two links.

\item \underline{\our is strictly more expressive than Neo-GNN and BUDDY.}

We have already shown that \our is strictly more expressive than NCN. In Theorem 2 of the NCN paper~\cite{wangneural}, it has been proved that NCN is more expressive than both Neo-GNN and BUDDY. It follows that \our is strictly more expressive than Neo-GNN and BUDDY as well.

\item \underline{\our is strictly more expressive than NBFNet.}

We prove that NBFNet is as expressive as a pure GNN. Therefore, since we have already proven that \our is strictly more expressive than pure GNNs, it immediately follows that \our is also strictly more expressive than NBFNet.

To complete the argument, we prove that NBFNet is as expressive as a pure GNN. 
First of all we report the formulation of NBFNet for simple undirected graph. Given a graph $G=(V ,E ,\mathbf{X} ^0)$, NBFNet assigns a representation $\mathbf{x}(u, v)$ to each edge $(u, v) \in E $. The iterative update rule follows a message-passing scheme:
\begin{equation}\label{eq:nbf}
\begin{aligned}
    \mathbf{x}^{(0)}_{(u, v)} &= \text{\small{INDICATOR}}(\mathbf{x}^0_u, \mathbf{x}^0_v), \\
    \mathbf{x}^{(l)}_{(u, v)} &= \text{\small{AGGREGATE}}\left( \left\{ \text{\small{MESSAGE}}(h^{(l-1)}_{(i, j)}) \mid (i, j) \in N(u, v) \right\} \cup \{ h^{(0)}_{(u, v)} \} \right)
\end{aligned}
\end{equation}


where $\text{INDICATOR}$ assigns an initial representation based on the nodes $u, v\in V $ and $N(u, v)$ is the set of edges incident to $(u, v)$.

We prove that, at any layer $l$, the representations of the two links produced by a pure GNN are equal if and only if also the ones produced by NBFNet are equal, i.e.,
\begin{equation}\label{eq:dimnbf}
\mathbf{x}^{\text{GNN}^l}_{(u,v)}=\mathbf{x}^{\text{GNN}^l}_{(i,j)} \Leftrightarrow \mathbf{x}^{\text{NBF}^l}_{(u,v)}=\mathbf{x}^{\text{NBF}^l}_{(i,j)} \quad \forall l 
\end{equation} 

where $\mathbf{x}^{\text{NBF}^l}_{(u,v)}$ and $\mathbf{x}^{\text{NBF}^l}_{(i,j)}$ are calculated via Equation \ref{eq:nbf}, while $\mathbf{x}^{\text{GNN}^l}_{(u,v)} \text{ and }\mathbf{x}^{\text{GNN}^l}_{(i,j)}$ are calculated following the standard message passing scheme reported below:
\begin{equation}\label{Def_GNN}
\begin{aligned}
    \mathbf{x}^{\text{GNN}^0}_v &= \mathbf{x}^0_v, \\
    \mathbf{x}^{\text{GNN}^l}_v &= \text{\small COMB}\left(\mathbf{x}^{\text{GNN}^{l-1}}_{v}, 
    \text{\small AGG}\left(\{\mathbf{x}^{\text{GNN}^{l-1}}_{u} \mid u \in N(v)\}\right)\right)\\
    \mathbf{x}^{\text{GNN}^l}_{(u,v)}&= g(\mathbf{x}^{\text{GNN}^l}_{u},\mathbf{x}^{\text{GNN}^l}_{v})
\end{aligned}
\end{equation}



Let the functions $\text{\small INDICATOR}$, $\text{\small AGGREGATE}$ and $\text{\small MESSAGE}$ of Equation \ref{eq:nbf}, as well as the functions $\text{\small COMB}$, $\text{\small AGG}$ and $g$ be injective. We prove Equation \ref{eq:dimnbf} by induction on the number of layer $l$.

\underline{\textbf{Base Case: $l=0$}}

\begin{align}
\mathbf{x}^{\text{GNN}^0}_{(u,v)}= \mathbf{x}^{\text{GNN}^0}_{(i,j)} \xLongleftrightarrow{\text{(\ref{Def_GNN})}}
g(\mathbf{x}^0_{u},\mathbf{x}^0_{v})=g(\mathbf{x}^0_{i},\mathbf{x}^0_{j}) &\xLongleftrightarrow{\text{inj}}
(\mathbf{x}^0_{u},\mathbf{x}^0_{v})=(\mathbf{x}^0_{i},\mathbf{x}^0_{j})\xLongleftrightarrow{\text{inj}}\nonumber\\ 
\xLongleftrightarrow{\text{inj}}\text{\small INDICATOR}(\mathbf{x}^0_{u},\mathbf{x}^0_{v})=\text{\small INDICATOR}&(\mathbf{x}^0_{i},\mathbf{x}^0_{j})\xLongleftrightarrow{(\ref{eq:nbf})}\mathbf{x}^{\text{NBF}^0}_{(u,v)}=\mathbf{x}^{\text{NBF}^0}_{(i,j)}\nonumber
\end{align}

\underline{\textbf{Inductive Step}}
We assume Equation \ref{eq:dimnbf} holds for $l-1$ and prove it holds for $l$. 

In particular, we want to prove

\begin{equation}\label{eq:dimfin}
\mathbf{x}_{(u,v)}^{\text{GNN}^{l}} = \mathbf{x}_{(i,j)}^{\text{GNN}^{l}} \xLongleftrightarrow{ } \mathbf{x}_{(u,v)}^{\text{NBF}^{l}} = \mathbf{x}_{(i,j)}^{\text{NBF}^{l}}
\end{equation}
using the inductive hypothesis 
\begin{equation}\label{eq:indhyp}
\mathbf{x}_{(u,v)}^{\text{GNN}^{l-1}} = \mathbf{x}_{(i,j)}^{\text{GNN}^{l-1}} \xLongleftrightarrow{ } \mathbf{x}_{(u,v)}^{\text{NBF}^{l-1}} = \mathbf{x}_{(i,j)}^{\text{NBF}^{l-1}}
\end{equation}
Applying Equation \ref{Def_GNN} to the left-hand side of Equation \ref{eq:dimfin} we get

\begin{align}
\mathbf{x}_{(u,v)}^{\text{GNN}^{l}} &= \mathbf{x}_{(i,j)}^{\text{GNN}^{l}}\nonumber\\ 
&\xLongleftrightarrow{(\ref{Def_GNN})} \nonumber\\
g(\text{\small COMB}(\mathbf{x}_u^{\text{GNN}^{l-1}}, \text{\small AGG}(\{\mathbf{x}_x^{\text{GNN}^{l-1}}\mid x \in N(u)\})) &, \text{\small COMB}(\mathbf{x}_v^{\text{GNN}^{l-1}},\text{\small AGG}(\{\mathbf{x}_y^{\text{GNN}^{l-1}}\mid y \in N(u)\})))\nonumber\\
&=\nonumber\\
g(\text{\small COMB}(\mathbf{x}_i^{\text{GNN}^{l-1}}, \text{\small AGG}(\{\mathbf{x}_m^{\text{GNN}^{l-1}}\mid m \in N(i)\})) &, \text{\small COMB}(\mathbf{x}_j^{\text{GNN}^{l-1}},\text{\small AGG}(\{\mathbf{x}_n^{\text{GNN}^{l-1}}\mid n \in N(j)\}))).\nonumber
\end{align}

Given the injectivity of $g,\text{\small COMB} \text{ and } \text{\small AGG}$, this is equivalent to 

\begin{align}
\mathbf{x}_{u}^{\text{GNN}^{l-1}} = \mathbf{x}_{i}^{\text{GNN}^{l-1}} \wedge \{\mathbf{x}_x^{\text{GNN}^{l-1}}&\mid x \in N(u)\}=\{\mathbf{x}_m^{\text{GNN}^{l-1}}\mid m \in N(i)\} \wedge \nonumber\\
\wedge \text{ }\mathbf{x}_{v}^{\text{GNN}^{l-1}} = \mathbf{x}_{j}^{\text{GNN}^{l-1}} \wedge \{\mathbf{x}_y^{\text{GNN}^{l-1}}&\mid y \in N(v)\}=\{\mathbf{x}_n^{\text{GNN}^{l-1}}\mid n \in N(j)\} \nonumber\\
&\xLongleftrightarrow{ } \nonumber\\
\{(\mathbf{x}_u^{\text{GNN}^{l-1}},\mathbf{x}_x^{\text{GNN}^{l-1}})\mid x \in N(u)\}&=\{(\mathbf{x}_i^{\text{GNN}^{l-1}},\mathbf{x}_m^{\text{GNN}^{l-1}})\mid m \in N(i)\} \nonumber\\
 &\wedge \nonumber\\
 \{(\mathbf{x}_v^{\text{GNN}^{l-1}},\mathbf{x}_y^{\text{GNN}^{l-1}})\mid y \in N(v)\}&=\{(\mathbf{x}_j^{\text{GNN}^{l-1}},\mathbf{x}_n^{\text{GNN}^{l-1}})\mid n \in N(j)\} \nonumber\\
&\xLongleftrightarrow{ } \nonumber\\
\{(\mathbf{x}_u^{\text{GNN}^{l-1}},\mathbf{x}_x^{\text{GNN}^{l-1}})\mid x \in N(u)\}&\cup\{(\mathbf{x}_v^{\text{GNN}^{l-1}},\mathbf{x}_y^{\text{GNN}^{l-1}})\mid y \in N(v)\} \nonumber\\
 &= \nonumber\\
 \{(\mathbf{x}_i^{\text{GNN}^{l-1}},\mathbf{x}_m^{\text{GNN}^{l-1}})\mid m \in N(i)\}&\cup\{(\mathbf{x}_j^{\text{GNN}^{l-1}},\mathbf{x}_n^{\text{GNN}^{l-1}})\mid n \in N(j)\}. \nonumber
\end{align}

By Definition of $N(u,v)$ (Equation \ref{eq:nbf}), this is equivalent to 

\begin{align}
\{(\mathbf{x}_w^{\text{GNN}^{l-1}},\mathbf{x}_t^{\text{GNN}^{l-1}})\mid (w,t) \in N(u,v)\}&=\{(\mathbf{x}_a^{\text{GNN}^{l-1}},\mathbf{x}_b^{\text{GNN}^{l-1}})\mid (a,b) \in N(i,j)\} \nonumber\\
&\xLongleftrightarrow{ \text{inj}}\nonumber\\
\{g(\mathbf{x}_w^{\text{GNN}^{l-1}},\mathbf{x}_t^{\text{GNN}^{l-1}})\mid (w,t) \in N(u,v)\}&=\{g(\mathbf{x}_a^{\text{GNN}^{l-1}},\mathbf{x}_b^{\text{GNN}^{l-1}})\mid (a,b) \in N(i,j)\} \nonumber\\
&\xLongleftrightarrow{(\ref{Def_GNN})}\nonumber\\
\{\mathbf{x}_{(w,t)}^{\text{GNN}^{l-1}}\mid (w,t) \in N(u,v)\}&=\{\mathbf{x}_{(a,b)}^{\text{GNN}^{l-1}}\mid (a,b) \in N(i,j)\} \nonumber\\
&\xLongleftrightarrow{ \text{IND. HYP.}(\ref{eq:indhyp})}\nonumber\\
\{\mathbf{x}_{(w,t)}^{\text{NBF}^{l-1}}\mid (w,t) \in N(u,v)\}&=\{\mathbf{x}_{(a,b)}^{\text{NBF}^{l-1}}\mid (a,b) \in N(i,j)\}. \nonumber
\end{align}
Using the hypotheses of injective \text{\small AGG} and \text{\small MESSAGE}, this is equivalent to:
\begin{align}
\text{\small AGG} (\{\text{\small MESSAGE}(\mathbf{x}_{(w,t)}^{\text{NBF}^{l-1}})\mid (w,t) \in N(u,v)\})&=\text{\small AGG}(\{\text{\small MESSAGE}(\mathbf{x}_{(a,b)}^{\text{NBF}^{l-1}})\mid (a,b) \in N(i,j)\})\nonumber\\ 
&\xLongleftrightarrow{ (\ref{eq:nbf})}\nonumber\\  
\mathbf{x}_{(u,v)}^{\text{NBF}^{l}} &= \mathbf{x}_{(i,j)}^{\text{NBF}^{l}}
\end{align}

which complete the proof.
\end{itemize}

\end{proof}
