\subsection{The cup product on polygons}\label{subsec:CupOnPolygons}
As advertised earlier, we can extend the definitions of the discrete wedge product to any $p$--polygon such that it still satisfies the defining properties of a cup product (Definition \ref{def:GeneralCupProduct}) and therefore automatically also the properties of Proposition \ref{prop:GeneralCup}. Moreover, we show that our polygonal cup product is a skew--commutative bilinear operation on any polygonal forms, not just on closed ones, viz. the Proposition \ref{prop:PolygonalCup}.

Let us remember that a discrete $q$--form $\alpha^q$ is a $q$--cochain defined per each element of a $q$--chain $C_q(K)$:
\[
 \alpha^q = \alpha(c_0),\dots,\alpha(c_p) ,\;\; c_i\in C_q(K).
\]
Furthermore, we sum two discrete $q$--forms $\alpha^q,\beta^q$ by summing their values per each element of a $q$--chain $C_q(K)$ and multiply a $q$--form $\alpha^q$ by a scalar $t\in\Re$ in element--wise fashion too:
\begin{align}
\alpha^q + \beta^q &= (\alpha +\beta)(c_0),\dots,(\alpha +\beta)(c_p), \label{eq:polygonalSum}\\
t\cdot \alpha^q &= t\cdot \alpha(c_0),\dots,t\cdot \alpha(c_p).\label{eq:polygonalScalarMultiplication}
\end{align}


\begin{definition}\label{def:PolygonalCup}
Let $K$ be a 2--pseudomanifold whose 2--cells (faces) are polygons. The cup product $C^k(K,\Re)\times C^l(K,\Re)\rightarrow C^{k+l}(K,\Re)$ of two discrete forms $\alpha^k,\beta^l$ is a $(k+l)$--form $\alpha^k\cup\beta^l$ defined on each $(k+l)$--cell of $C_{k+l}(K)$ in the following fashion:\\
Let $f=(v_0,\dots,v_{p-1})$ be a $p$--polygonal face, $(v_i,v_j)$ an edge, and $v$ a vertex of $K$, the \textbf{polygonal cup product} is defined for each degree and per each $(k+l)$--cell as:
\begin{align}
(\alpha^0\cup\beta^0)(v)  &=  \alpha(v)\beta(v), \label{eq:PolygonalCup00} \\
(\alpha^0\cup\beta^1)(v_i,v_j)  &=  \frac{1}{2}(\alpha(v_i)+\alpha(v_{j}))\beta(v_i,v_j),\label{eq:PolygonalCup01} \\
(\alpha^0\cup\beta^2)(f) &=\frac{1}{p}\bigg( \sum_{i=0}^{p-1}\alpha(v_i) \bigg) \beta(f),\label{eq:PolygonalCup02}   \\
(\alpha^1\cup\beta^1)(f) &= \sum_{a=1}^{\lfloor\frac{p-1}{2} \rfloor} \bigg( \frac{1}{2} - \frac{a}{p} \bigg) \sum_{i=0}^{p-1} \alpha(i)(\beta((i+a)\%p) - \beta((i-a)\%p)),\label{eq:PolygonalCup11}
\end{align}
where $\alpha(i):=\alpha(e_i)=\alpha(v_i,v_{(i+1)\%p})$ and $\%p$ means modulo $p$.
\end{definition}

It is easy to see that the simplicial and cubical cup products (Definitions \ref{def:SimplicialCup} and \ref{def:CubicalCup}) are just special cases of the product defined above.

In Theorem \ref{theo:PolygonalCupIsCup} we prove that the polygonal cup product actually \textit{is} a cup product, that is, we prove that it satisfies the defining properties of a cup product (Definition \ref{def:GeneralCupProduct}). But we first prove, in the following lemma, that it obeys the Leibniz rule with the discrete derivative.

\begin{lemma}\label{lemma:LeibnizPolygonalCup}
 The discrete wedge product from Definition \ref{def:PolygonalCup} satisfies the Leibniz rule with the discrete derivative, that is:
 \begin{align*}
d_0(\alpha^0\cup\beta^0) &=  d_0\alpha\cup\beta + \alpha\cup d_0\beta,\\
d_1(\alpha^0\cup\beta^1) &=  d_0\alpha\cup\beta + \alpha\cup d_1\beta.
\end{align*}
For $d(\alpha^0\cup\beta^2)$ and $d(\alpha^1\cup\beta^1)$ we get trivially 0 because there are no 3--dimensional chains (and thus no 3--forms) on a 2--dimensional pseudomanifold.
\end{lemma}

\begin{proof} We will prove the Leibniz rule for each degree separately.
\textbf{The case $d(\alpha^0\cup\beta^0)$:} let $e=(v_i,v_j)$ be an edge of $K$, then
\begin{align*}
 (d_0\alpha\cup\beta + \alpha\cup d_0\beta)(e) &= (\alpha(v_{j})-\alpha(v_i))\frac{\beta(v_i)+\beta(v_{j})}{2}\\
 &+ \frac{\alpha(v_i)+\alpha(v_{j})}{2}(\beta(v_{j})-\beta(v_i))\\
 & = \frac{\beta(v_i)(-2\alpha(v_i)) + \beta(v_{j})(2\alpha(v_{j}))}{2}\\
 & = \alpha(v_{j})\beta(v_{j}) - \alpha(v_i)\beta(v_i) \\
 & = (\alpha\cup\beta)(v_{j}) - (\alpha\cup\beta)(v_i)\\
 & = d_0(\alpha^0\cup\beta^0)(e).
\end{align*}

\textbf{The case $d(\alpha^0\cup\beta^1)$:} Let us first simplify the notation and denote $\alpha_i = \alpha^0(v_i)$, $\beta_i=\beta^1(e_i)$. Let also any index $i$ to be understood as $i\%n$. Let $f=(v_0,\dots,v_{n-1})$ be an $n$--polygonal face with edges $e_i=(v_i,v_{i+1})$. Due to the indexes being cyclic (modulo $n$), we can reorder the following sums in this manner:
\begin{align*}
 d(\alpha^0\cup\beta^1)(f) & = \sum_{i=0}^{n-1} \frac{\alpha_i + \alpha_{i+1}}{2}\beta_i = \sum_{i=0}^{n-1} \frac{\beta_{i-1} + \beta_{i}}{2}\alpha_i\\
 (d\alpha^0\cup\beta^1)(f) & = \sum_{i=0}^{n-1} \sum_{a=1}^{\lfloor\frac{n-1}{2} \rfloor} \bigg(\frac{1}{2}-\frac{a}{n}\bigg)(\alpha_{i+1} - \alpha_i)(\beta_{i+a} - \beta_{i-a}) \\
 & = \sum_{i=0}^{n-1} \sum_{a=1}^{\lfloor\frac{n-1}{2} \rfloor} \frac{n-2a}{2n}(\alpha_i)(\beta_{i+a-1} - \beta_{i-a-1} - \beta_{i+a} + \beta_{i-a})\\
 (\alpha^0\cup d\beta^1)(f)& = \frac{1}{n}\sum_{i=0}^{n-1}\alpha_i \sum_{i=0}^{n-1}\beta_i
\end{align*}
Thus we want to show that
\[
 \sum_{i=0}^{n-1} \alpha_i \frac{\beta_{i-1} + \beta_{i}}{2}
 = \sum_{i=0}^{n-1}\frac{\alpha_i}{2n}\bigg[ \sum_{a=1}^{\lfloor\frac{n-1}{2} \rfloor} (n-2a)(\beta_{i+a-1} - \beta_{i+a} + \beta_{i-a} - \beta_{i-a-1})
+ 2\sum_{j=0}^{n-1}\beta_j\bigg],
\]
but instead we will show that the following equation (\ref{eq:Alpha0ToExpandLeibniz}) holds for any $i\in\{0,\dots,n-1\}$, which implies that also the equality above is true.
\begin{equation}\label{eq:Alpha0ToExpandLeibniz}
\frac{\beta_{i-1} + \beta_{i}}{2} = \frac{1}{2n}\bigg[\sum_{a=1}^{\lfloor\frac{n-1}{2} \rfloor} (n-2a)(\beta_{i+a-1} - \beta_{i+a} + \beta_{i-a} - \beta_{i-a-1}) + 2\sum_{j=0}^{n-1}\beta_j\bigg]
\end{equation}

If $n$ is even, then $a=1,\dots,\lfloor\frac{n-1}{2} \rfloor$ is equivalent to $a = 1,2,\dots,\frac{n}{2}-1$, and if $n$ is odd, then it is equivalent to $a= 1,\dots,\frac{n-1}{2}$. Thus we will first show the validity of (\ref{eq:Alpha0ToExpandLeibniz}) for $n$ even and then for $n$ odd.

\textbf{For $n$ even} we compute:
\begin{align*}
\sum_{a=1}^{\frac{n}{2}-1}(n-2a)&(\beta_{k+a-1} - \beta_{k+a}) = (n-2)(\beta_{k} - \beta_{k+1})+(n-4)(\beta_{k+1} - \beta_{k+2})\\
  &\;+ (n-6)(\beta_{k+2} - \beta_{k+3}) + \cdots + 6(\beta_{k+\frac{n}{2}-4} - \beta_{k+\frac{n}{2}-3})\\
  &\;+ 4(\beta_{k+\frac{n}{2}-3} - \beta_{k+\frac{n}{2}-2}) + 2(\beta_{k+\frac{n}{2}-2} - \beta_{k+\frac{n}{2}-1})\\
  =&\; n\beta_k - 2(\beta_k + \beta_{k+1} + \beta_{k+2} +  \beta_{k+3} +\dots\\
  & + \beta_{k+\frac{n}{2}-3} + \beta_{k+\frac{n}{2}-2} + \beta_{k+\frac{n}{2}-1}),\\
%=======
\sum_{a=1}^{\frac{n}{2}-1}(n-2a)&(\beta_{k-a} - \beta_{k-a-1}) = (n-2)(\beta_{k-1} - \beta_{k-2})+(n-4)(\beta_{k-2} - \beta_{k-3})\\
  &\;+ (n-6)(\beta_{k-3} - \beta_{k-4}) + \cdots + 6(\beta_{k-\frac{n}{2}+3} - \beta_{k-\frac{n}{2}+2}) \\
  &\;+ 4(\beta_{k-\frac{n}{2}+2} - \beta_{k-\frac{n}{2}+1}) + 2(\beta_{k-\frac{n}{2}+1} - \beta_{k-\frac{n}{2}})\\
  =&\; n\beta_{k-1} - 2(\beta_{k-1} + \beta_{k-2} +  \beta_{k-3} +
  \dots\\
  &+ \beta_{k+\frac{n}{2}+2} + \beta_{k+\frac{n}{2}+1} + \beta_{k+\frac{n}{2}}).
\end{align*}
Thus
\begin{align*}
 \sum_{a=1}^{\frac{n}{2}-1}(n-2a)(\beta_{k+a-1}-\beta_{k+a}+\beta_{k-a} -\beta_{k-a-1} ) &= n(\beta_{k-1}+\beta_k) -2\sum_{i=k}^{k+n-1}\beta_i \\
 &= n(\beta_{k-1}+\beta_k) -2\sum_{j=0}^{n-1}\beta_j
\end{align*}
and for $n$ even we obtain
\[
\frac{1}{2n}\bigg[\sum_{a=1}^{\lfloor\frac{n-1}{2} \rfloor}(n-2a)(\beta_{k+a-1}-\beta_{k+a}+\beta_{k-a} -\beta_{k-a-1} ) + 2\sum_{j=0}^{n-1}\beta_j\bigg] = \frac{\beta_{k-1}+\beta_k}{2}.
\]

\textbf{For $n$ odd} we proceed in a similar fashion:
\begin{align*}
\sum_{a=1}^{\frac{n-1}{2}}(n-2a)&(\beta_{k+a-1} - \beta_{k+a}) = (n-2)(\beta_{k} - \beta_{k+1})+(n-4)(\beta_{k+1} - \beta_{k+2})\\
  &\;+ (n-6)(\beta_{k+2} - \beta_{k+3}) + \cdots + 5(\beta_{k+\frac{n-1}{2}-3} - \beta_{k+\frac{n-1}{2}-2})\\
  &\;+ 3(\beta_{k+\frac{n-1}{2}-2} - \beta_{k+\frac{n-1}{2}-1}) + 2(\beta_{k+\frac{n-1}{2}-1} - \beta_{k+\frac{n-1}{2}})\\
  =&\; n\beta_k - 2(\beta_k + \beta_{k+1} + \beta_{k+2} +  \beta_{k+3} +\dots+ \beta_{k+\frac{n-1}{2}-2} + \beta_{k+\frac{n-1}{2}-1}) \\
  &- \beta_{k+\frac{n-1}{2}},\\
%=======
\sum_{a=1}^{\frac{n-1}{2}}(n-2a)&(\beta_{k-a} - \beta_{k-a-1}) = (n-2)(\beta_{k-1} - \beta_{k-2})+(n-4)(\beta_{k-2} - \beta_{k-3})\\
  &\;+ (n-6)(\beta_{k-3} - \beta_{k-4}) + \cdots + 5(\beta_{k-\frac{n-1}{2}+2} - \beta_{k-\frac{n-1}{2}+1}) \\
  &\;+ 3(\beta_{k-\frac{n-1}{2}+1} - \beta_{k-\frac{n-1}{2}}) + (\beta_{k-\frac{n-1}{2}} - \beta_{k-\frac{n-1}{2}-1})\\
  =&\; n\beta_{k-1} - 2(\beta_{k+\frac{n-1}{2}+1} + \beta_{k+\frac{n-1}{2}+2} +\dots+ \beta_{k-3} + \beta_{k-2} +  \beta_{k-1})\\
  &- \beta_{k+\frac{n-1}{2}}.
\end{align*}
Thus
\begin{align*}
 \sum_{a=1}^{\frac{n-1}{2}}(n-2a)(\beta_{k+a-1}-\beta_{k+a}+\beta_{k-a} -\beta_{k-a-1} ) &= n(\beta_{k-1}+\beta_k) -2\sum_{i=k}^{k+n-1}\beta_i \\
 &= n(\beta_{k-1}+\beta_k) -2\sum_{j=0}^{n-1}\beta_j
\end{align*}
and for $n$ odd we get
\[
\frac{1}{2n}\bigg[\sum_{a=1}^{\lfloor\frac{n-1}{2} \rfloor}(n-2a)(\beta_{k+a-1}-\beta_{k+a}+\beta_{k-a} -\beta_{k-a-1} ) + 2\sum_{j=0}^{n-1}\beta_j\bigg] = \frac{\beta_{k-1}+\beta_k}{2}.
\]
We have shown that the equality (\ref{eq:Alpha0ToExpandLeibniz}) holds for any $i\in\{ 0,1,\dots,n-1\}$, which implies $d_1(\alpha^0\cup\beta^1)=d_0\alpha\cup\beta + \alpha\cup d_1\beta$.
\end{proof}
%
%========================================
%

Now we are ready to claim that our discrete wedge product on polygonal pseudomanifolds is a cup product:

\begin{theorem}\label{theo:PolygonalCupIsCup}
The polygonal cup product from Definition \ref{def:PolygonalCup} is a cup product, i.e., it satisfies the Definition \ref{def:GeneralCupProduct}.
\end{theorem}

\begin{proof}
From the formulas (\ref{eq:PolygonalCup00})--(\ref{eq:PolygonalCup11}) and the way we sum two discrete forms (eq. \ref{eq:polygonalSum}) or multiply them by scalar (eq. \ref{eq:polygonalScalarMultiplication}), it is a simple exercise to see that
$\forall t\in\Re,\; \forall c_i\in C_{k+l}, 0\leq (k+l) \leq 2$:
\begin{align*}
(t\cdot\alpha^k\cup\beta^l)(c_i)  &= (\alpha^k\cup t\cdot\beta^l)(c_i),\\
((\alpha^k_1 + \alpha^k_2) \cup\beta^l)(c_i)  &= (\alpha^k_1 \cup\beta^l)(c_i) +
(\alpha^k_2 \cup\beta^l)(c_i),\\
(\alpha^k \cup (\beta^l_1 + \beta^l_2)(c_i)  &= (\alpha^k \cup\beta^l_1)(c_i) +
(\alpha^k \cup\beta^l_2)(c_i).
\end{align*}
Therefore the polygonal cup product is a \textit{bilinear} operation.

It also satisfies item 1 of Definition \ref{def:GeneralCupProduct} -- the result of product of two forms is located on a face that is incident to both the elements where the two original discrete forms reside.

Due to Lemma \ref{lemma:LeibnizPolygonalCup}, our product satisfies item 2, the Leibniz rule.

We will now prove that item 3 of Definition \ref{def:GeneralCupProduct} also holds. A pseudomanifold $K$ as we defined it is a connected cell complex, therefore we have to show that there exist a real number $\xi$ such that $I^0\cup \alpha^p = \alpha^p\cup I^0 = \xi\alpha^p$, where $I^0$ is the constant 0--form that takes value 1 on the vertices of $K$. Using the equations of Definition \ref{def:PolygonalCup}, we can thus write:
 \begin{align*}
  I^0\cup\alpha^0 &= \sum_{v_i\in V(K)}I^0\cup\alpha^0(v_i) =  \sum_{v_i\in V}I^0(v_i)\alpha^0(v_i) = \sum_{v_i\in V}1\alpha^0(v_i) = 1\alpha^0,\\
  \alpha^0\cup I^0 &= \sum_{v_i\in V}\alpha^0\cup I^0(v_i) = \sum_{v_i\in V}\alpha^0(v_i)I^0(v_i) = \sum_{v_i\in V}\alpha^0(v_i)1 = 1\alpha^0,\\
  I^0\cup\alpha^1 &= \sum_{(v_i,v_j)\in E(K)}I^0\cup\alpha^1(v_i,v_j) = \sum_{(v_i,v_j)\in E}\frac{I^0(v_i)+I^0(v_j)}{2}\alpha^1(v_i,v_j) \\
  &= \sum_{(v_i,v_j)\in E}\frac{1+1}{2}\alpha^1(v_i,v_j) = 1\alpha^1,\\
  \alpha^1\cup I^0 &= \sum_{(v_i,v_j)\in E}\alpha^1\cup I^0(v_i,v_j) = \sum_{(v_i,v_j)\in E}\alpha^1(v_i,v_j)\frac{I^0(v_i)+I^0(v_j)}{2} \\
  &= \sum_{(v_i,v_j)\in E}\alpha^1(v_i,v_j) \frac{1+1}{2}= 1\alpha^1,\\
  I^0\cup\alpha^2 &= \sum_{f_i\in F(K)}I^0\cup\alpha^2(f_i) = \sum_{f_i\in F}\sum_{v_j\prec f_i}\frac{I^0(v_j)}{p_i}\alpha^2(f_i) \\
  &= \sum_{f_i\in F}\frac{p_i}{p_i}\alpha^2(f_i) = 1\alpha^2,\\
  \alpha^2\cup I^0 &= \sum_{f_i\in F}\alpha^2\cup I^0(f_i) = \sum_{f_i\in F}\alpha^2(f_i)\sum_{v_j\prec f_i}\frac{I^0(v_j)}{p_i} \\
  &= \sum_{f_i\in F}\alpha^2(f_1)\frac{p_i}{p_i}= 1\alpha^2,
 \end{align*}
where $p_i$ is the number of vertices of a face $f_i$. We thus conclude that $\xi=1$ satisfies $I^0\cup \alpha^p = \alpha^p\cup I^0 = \xi\alpha^p \;\; \forall p\in\{0,1,2\}$.
\end{proof}

In the following proposition, which can be thought of as an analog of Proposition \ref{prop:wedgeProduct}, we summarize and prove further properties of our polygonal cup product.

\begin{proposition}\label{prop:PolygonalCup}
Let $K$ be a 2--pseudomanifold, $\alpha^k \in C^k(K)$, $\beta^l \in C^l(K)$, and $\gamma^m \in C^m(K)$.
The polygonal cup product from Definition \ref{def:PolygonalCup} satisfies these properties:
\begin{enumerate}
 \item Bilinearity.
 \item Skew--commutativity $\alpha^k \cup\beta^l = (-1)^{kl} \beta^l\cup\alpha^k$.
 \item Leibniz rule.
 \item Associativity under the following conditions:\\
    $\alpha^0\cup(\beta^0\cup\gamma^0)=(\alpha^0\cup\beta^0)\cup\gamma^0$ always,\\
    $\alpha^0\cup(\beta^0\cup\gamma^1)=(\alpha^0\cup\beta^0)\cup\gamma^1$ if $d\alpha^0 = 0$ or $d\beta^0 = 0$,\\
    $\alpha^0\cup(\beta^0\cup\gamma^2)=(\alpha^0\cup\beta^0)\cup\gamma^2$ if $d\alpha^0 = 0$ or $d\beta^0 = 0$,\\
    $\alpha^0\cup(\beta^1\cup\gamma^1)=(\alpha^0\cup\beta^1)\cup\gamma^1$ if $d\alpha^0 = 0$.
\end{enumerate}
\end{proposition}

\begin{proof}
 From Theorem \ref{theo:PolygonalCupIsCup} we know our product is a \textit{bilinear} operation satisfying the \textit{Leibniz rule} with discrete exterior derivative. We now show that it is also skew--commutative on any discrete forms and associative in the declared fashion.\\
 With respect to the announced form of \textit{associativity}, in the case of the product of three 0--forms we get to multiplying three real numbers on each vertex, which is indeed an associative operation. For the other degrees, we have learned in the proof of Theorem \ref{theo:PolygonalCupIsCup} that if $K$ is connected and a 0--form $\alpha^0$ is constant (which is equivalent to closed), that is $\alpha^0(v_i)= \rho\in\mathbb{R}\;\forall v_i\in K$, then the cup product of $\alpha^0$ with any $q$--form $\omega^q$ is equal to multiplying $\omega^q$ by the real number $\rho$. This fact yields:
 \[
   (\alpha^0\cup\beta^k)\cup\gamma^l = (\rho\beta^k)\cup\gamma^l = \rho(\beta^k\cup\gamma^l) =\alpha^0\cup(\beta^k\cup\gamma^l),
 \]
 which proves the statement of item 4.\\
 Concerning the \textit{skew--commutativity}, looking at the equations (\ref{eq:PolygonalCup00})--(\ref{eq:PolygonalCup02}) it is easy to see that $\alpha^0 \cup\beta^l = \beta^l\cup\alpha^0$ for $l=0,1,2$. The case of the product of two 1--forms is slightly more involving. We need to prove that $(\alpha^1\cup\beta^1)(f) = - (\beta^1\cup\alpha^1)(f)$ on an $n$--polygonal face $f=(v_0,\dots,v_{n-1})$. Let us remember that
 \[
 (\alpha^1\cup\beta^1)(f) = \sum_{a=1}^{\lfloor\frac{n-1}{2} \rfloor} \bigg( \frac{1}{2} - \frac{a}{n} \bigg) \sum_{i=0}^{n-1} \alpha(i)(\beta((i+a)\%n) - \beta((i-a)\%n),
 \]
where $\alpha(i):=\alpha(e_i)=\alpha(v_i,v_{(i+1)\%n})$ and $\%n$ means modulo $n$. Again, to simplify the notation we will omit writing the symbol $\%n$ in the indexes and by some index $k$ we will always understand $k\%n$. We next show that
\[
\sum_{i=0}^{n-1} \alpha(i)(\beta(i+a) - \beta(i-a)) = -\sum_{i=0}^{n-1} \beta(i)(\alpha(i+a) - \alpha(i-a)).
\]
Due to the indexes being cyclic (modulo $n$), we can write:
\small
\begin{align*}
 \sum_{i=0}^{n-1} \alpha(i)\beta(i+a) &= \alpha(0)\beta(a) + \alpha(1)\beta(1+a) + \cdots + \alpha(n-a-1)\beta(n-1)\\
 &+ \alpha(-a)\beta(0) + \alpha(1-a)\beta(1) + \alpha(2-a)\beta(2) + \cdots\\
 &+ \alpha(n-1)\beta(n-1+a)\\
 &= \sum_{j=0}^{n-1} \beta(j)\alpha(j-a),\\
 \sum_{i=0}^{n-1} \alpha(i)\beta(i-a) &= \alpha(0)\beta(-a) + \alpha(1)\beta(1-a) + \cdots + \alpha(n+a-1)\beta(n-1)\\
 &+ \alpha(a)\beta(0) + \alpha(1+a)\beta(1) + \alpha(2+a)\beta(2) + \cdots \\
 &+ \alpha(n-1)\beta(n-1-a)\\
 &= \sum_{j=0}^{n-1} \beta(j)\alpha(j+a).
\end{align*}
\normalsize
Thus
\begin{align*}
(\alpha^1\cup\beta^1)(f) &= - \sum_{a=1}^{\lfloor\frac{n-1}{2} \rfloor} \bigg( \frac{1}{2} - \frac{a}{n} \bigg) \sum_{i=0}^{n-1} \beta(i)\big(\alpha((i+a)\%n) - \alpha((i-a)\%n)\big)\\
&= -(\beta^1\cup\alpha^1)(f).
\end{align*}
Hence the polygonal cup product is skew--commutative on cochain level.
\end{proof}



%%=============================================================%%
\section{Conclusion}\label{sec13}
We have presented a new definition of discrete wedge product on polygonal 2--pseudomanifolds (Definition \ref{def:PolygonalCup}) and proved that this polygonal wedge product satisfies the Leibniz product rule with discrete exterior derivative (Lemma \ref{lemma:LeibnizPolygonalCup}). We have also shown that the polygonal wedge product is a cup product (Theorem \ref{theo:PolygonalCupIsCup}). Moreover, in Proposition \ref{prop:PolygonalCup} we have proved that the polygonal wedge product shares further properties with the wedge product of differential forms, such skew--commutativity.




