The special case where every action has a constant execution time, i.e., the $t_i$'s are constant, is particularly useful for this purpose; we refer to this as the \emph{constant action execution time model}. 





\subsection{Stationary Equilibrium}
The following definition is similar to that of a stationary mean-field equilibrium in \cite{lions,adlakha}, but more appropriate in our context.

  \begin{definition}\label{def:stationary_ne}
 A {\em stationary equilibrium} of the game $\mathcal{G}$ is a pair of a mass distribution $\boldsymbol{\mu}^\dagger\in\mathcal{U}_m(A)$ and a stationary strategy $\boldsymbol{\sigma}^\dagger\in\mathcal{P}(A)$ 
such that
\begin{enumerate}
    \item[(a)] %all the agents use strategy $\sigma$ and exactly $\mu_i$ mass of agents choose action $i$, 
   $\boldsymbol{\mu}^\dagger$ is compatible with the stationary strategy $\boldsymbol{\sigma}^\dagger$, i.e., 
   $\mu^\dagger_i = \theta \sigma^\dagger(i) \tau_i(\boldsymbol{\mu}^\dagger)$ for some  normalizing $\theta$ such that $\sum_{j\in A}\mu^\dagger_j=m$.
  % \[\mu^\dagger_i=\sigma^\dagger_i\tau_i(\boldsymbol{\mu}^\dagger)\sum_{j=1}^{n}\frac{\mu^\dagger_j}{\tau_j(\boldsymbol{\mu}^\dagger)},\quad\forall\> i\in A.\]
  % $m\sigma^\dagger(i)=\mu^\dagger_i$ for any $i\in A$.
    \item[(b)] $\boldsymbol{\sigma}^\dagger$ is optimal among all possible strategies, i.e.,
    \begin{equation}
     \label{eq:equilibrium_condition}
     V(\boldsymbol{\sigma}^\dagger,\boldsymbol{\tau}(\boldsymbol{\mu}^\dagger))=\sup\limits_{\boldsymbol{\sigma}\in \mathcal{P}(A)^{\mathbb{N}}}V(\boldsymbol{\sigma},\boldsymbol{\tau}(\boldsymbol{\mu}^\dagger)).
 \end{equation}
\end{enumerate}

 \end{definition}

If $(\boldsymbol{\sigma}^\dagger,\boldsymbol{\mu}^\dagger)$ is a stationary equilibrium, then all agents use the same stationary strategy $\boldsymbol{\sigma}^\dagger$ resulting in a  mass of agents proportional to $\sigma^\dagger(i) \tau_i(\boldsymbol{\mu}^\dagger)$ choosing action $i$ where the scale coefficient is $ \theta=\sum_{j\in A}\frac{\mu^\dagger_j}{\tau_j(\boldsymbol{\mu}^\dagger)}$.
Furthermore, given the mass distribution $\boldsymbol{\mu}^\dagger$ and the resulting sojourn times $\boldsymbol{\tau}(\boldsymbol{\mu}^\dagger)$, no agent wants to deviate from the strategy $\boldsymbol{\sigma}^\dagger$, i.e.,
 \eqref{eq:equilibrium_condition} holds. Note that  it suffices to specify a stationary equilibrium by the equilibrium distribution $\boldsymbol{\mu}^\dagger$ as the stationary strategy $\sigma^\dagger$ can be computed as a function of $\boldsymbol{\mu}^\dagger$ according to Definition \ref{def:stationary_ne}.(a) and the above formula of $\theta$. 
% \[\sigma^\dagger=\left(\frac{\frac{\mu_i^\dagger}{\tau_i(\boldsymbol{\mu}^\dagger)}}{\sum_{j\in A}\frac{\mu^\dagger_j}{\tau_j(\boldsymbol{\mu}^\dagger)}}\right)_{i\in A}.\]
We denote the set of stationary equilibria of $\mathcal{G}$ by $\mathcal{S}(\mathcal{G})$ which is a subset of $\mathcal{P}(A)$.

