\le\sum_{i\in X}r_{i}x_i(\boldsymbol{\mu}^\dagger)
\le\sum_{i\in A}r_{i}x_i(\boldsymbol{\mu}^\dagger)
=SW(\boldsymbol{\mu}^\dagger).
\end{equation}

For $i\notin X$,
\begin{equation}
\label{eq:pf_tmp0}
\sum_{i\notin X} r_i x_i(\boldsymbol{\mu}^*)
  \leq \sum_{i\notin X} \frac{r_i}{e^{\beta \tau_i(\boldsymbol{\mu}^*)}-1} \frac{e^{\beta \tau_i(\boldsymbol{\mu}^*)}-1}{\tau_i(\boldsymbol{\mu}^*)}\mu_i^*,
\end{equation}
and
\begin{equation}
\label{eq:pf_tmp1}
   \frac{r_i}{e^{\beta \tau_i(\boldsymbol{\mu}^*)}-1} \leq \frac{r_i}{e^{\beta \tau_i(\boldsymbol{\mu}^\dagger)}-1} 
   \leq \frac{r_l}{e^{\beta \tau_l(\boldsymbol{\mu}^\dagger)}-1},
\end{equation}
where the first inequality follows from Assumption~\ref{assum_sojourntime} for all $i\notin X$, and the
second is due to the equilibrium condition~\eqref{thm:stationary_equilibrium_eq} in Theorem~\ref{thm:stationary_equilibrium} for any $l\in A^\dagger$.
Also, 
\begin{equation}
\label{eq:pf_tmp2}
    \frac{e^{\beta \tau_i(\boldsymbol{\mu}^*)}-1}{\tau_i(\boldsymbol{\mu}^*)} \leq \beta M\,,
\end{equation}
by the definition of $\chi(\mathcal{G}(m,A,\boldsymbol{r},\boldsymbol{\tau},\beta))$ and Lemma~\ref{lem:M_increasing}.
Using~\eqref{eq:pf_tmp1} and~\eqref{eq:pf_tmp2} in~\eqref{eq:pf_tmp0} yields
\begin{equation}
\label{eq:pf_tmp3}
    \sum_{i\notin X} r_i x_i(\boldsymbol{\mu}^*) \leq
       \sum_{i\notin X} \frac{r_l}{e^{\beta \tau_l(\boldsymbol{\mu}^\dagger)}-1} \beta M \mu_i^* \leq
       \frac{r_l}{\tau_l(\boldsymbol{\mu}^\dagger)} M m
\end{equation}
for every $l\in A^\dagger$. Choosing a $l\in A^\dagger$ with the smallest ratio $r_l / \tau_l(\boldsymbol{\mu}^\dagger)$ gives 
the further bound
\begin{equation}
\label{eq:pf_tmp4}
    \frac{r_l}{\tau_l(\boldsymbol{\mu}^\dagger)} M m \leq M\sum_{i\in A} \frac{r_i}{\tau_i(\boldsymbol{\mu}^\dagger)} \mu^\dagger_i
    = M \ \text{SW}(\boldsymbol{\mu}^\dagger)
\end{equation}
Combining~\eqref{eq:ins1}, \eqref{eq:pf_tmp3} and \eqref{eq:pf_tmp4} yields
\begin{equation*}
    \text{SW}(\boldsymbol{\mu}^*) = \sum_{i\in X} r_i x_i(\boldsymbol{\mu}^*) + \sum_{i\notin X} r_i x_i(\boldsymbol{\mu}^*) 
    \leq (M + 1) \ \text{SW}(\boldsymbol{\mu}^\dagger)\,.
\end{equation*}
Therefore, $\text{PoA}\le M+1$.


For the lower bound, we give a sequence of instances  for which the ratio inside the supremum in \eqref{eq:PoA_definition} approaches $M+1$. Consider the constant action execution time model with $n=2$ and execution times $t_1$, $t_2$. Assume the resource supply rate $b_2$ is infinite, that is, $w_2$ is always equal to 0.  Let
\[M=\frac{e^{\beta t_2}-1}{\beta t_2}\ge \frac{e^{\beta t_1}-1}{\beta t_1}.\]
Let
\[\frac{r_1}{e^{\beta(t_1+w_1)}-1}=\frac{r_2}{e^{\beta t_2}-1},\]
and
\[b_1(t_1+w_1)=m.\]
Then, at the equilibrium all agents choose action 1. The social welfare will only increase if the %platform has full control of the agents, it can let $b_1t_1$ mass of agents execute action $1$ and the 
mass $b_1 w_1 = m - b_1 t_1$ of agents waiting for action $1$ take action $2$ instead.
%remaining $m - b_1 t_1$ execute action $2$. 
%This distribution of agents may be sub-optimal, but suffices for our purpose.  
%The PoA is computed as follows,
This gives the lower bound,
\begin{align*}
    \text{PoA}&\ge\frac{r_1b_1+r_2\frac{m-b_1t_1}{t_2}}{r_1b_1}=1+\frac{r_2(m-b_1t_1)}{t_2r_1b_1}\\
    &=1-\frac{\frac{r_2}{t_2}}{\frac{r_1}{t_1}}+\frac{\frac{r_2}{t_2}}{\frac{r_1}{t_1+w_1}}\frac{\frac{r_1}{e^{\beta(t_1+w_1)}-1}}{\frac{r_2}{e^{\beta t_2}-1}}\\
    &=1-\frac{\frac{e^{\beta t_2}-1}{\beta t_2}}{\frac{e^{\beta(t_1+w_1)}-1}{\beta t_1}}+\frac{\frac{e^{\beta t_2}-1}{\beta t_2}}{\frac{e^{\beta(t_1+w_1)}-1}{\beta (t_1+w_1)}}=1+\frac{\frac{e^{\beta t_2}-1}{\beta t_2}}{\frac{e^{\beta(t_1+w_1)}-1}{\beta (t_1+w_1)}\frac{t_1+w_1}{w_1}}\>.
\end{align*}
We let $w_1$ approach zero and $t_1=o(w_1)$. This can be done by letting $m$ be fixed, $b_1=\frac{m}{t_1+\sqrt{t_1}}$, and $t_1\rightarrow0$. Alternatively, we can let $b_1$ be fixed, $m=b_1(t_1+\sqrt{t_1})$,   and $t_1\rightarrow0$.  Eitherway, we have  $t_1+w_1\rightarrow0$ and  $\frac{t_1+w_1}{w_1}\rightarrow1$. Then, it follows that,
\[\frac{e^{\beta(t_1+w_1)}-1}{\beta(t_1+w_1)}\frac{t_1+w_1}{w_1}\rightarrow1.\]
Therefore, 
\[\text{PoA}\ge 1+\frac{\frac{e^{\beta t_2}-1}{\beta t_2}}{\frac{e^{\beta(t_1+w_1)}-1}{\beta (t_1+w_1)}\frac{t_1+w_1}{w_1}}\rightarrow 1+ \frac{e^{\beta t_2}-1}{\beta t_2}=M+1.\]




\section{Proof of Corollary \ref{coro:infinite_poa}}\label{appendix:proof_coro:infinite_poa}
Here we allow the parameter $M$ to vary.   We will give a sequence of instances with PoA approaching infinity. Similar to the sequence of instances given in the proof of Proposition \ref{prop:poa_m+1}, we still
   assume $n=2$ and let
\[M=\frac{e^{\beta t_2}-1}{\beta t_2}\ge \frac{e^{\beta t_1}-1}{\beta t_1}.\]
Similarly, let
\[\frac{r_1}{e^{\beta(t_1+w_1)}-1}=\frac{r_2}{e^{\beta t_2}-1},\]
and
\[b_1(t_1+w_1)=m.\]
Then we have at the equilibrium all agents choose action 1. The PoA is computed similarly as follows,
\begin{align*}
    \text{PoA}&\ge\frac{r_1b_1+r_2\frac{m-b_1t_1}{t_2}}{r_1b_1}=1+\frac{r_2(m-b_1t_1)}{t_2r_1b_1}\\
    &=1-\frac{\frac{r_2}{t_2}}{\frac{r_1}{t_1}}+\frac{\frac{r_2}{t_2}}{\frac{r_1}{t_1+w_1}}\frac{\frac{r_1}{e^{\beta(t_1+w_1)}-1}}{\frac{r_2}{e^{\beta t_2}-1}}\\
    &=1-\frac{\frac{e^{\beta t_2}-1}{\beta t_2}}{\frac{e^{\beta(t_1+w_1)}-1}{\beta t_1}}+\frac{\frac{e^{\beta t_2}-1}{\beta t_2}}{\frac{e^{\beta(t_1+w_1)}-1}{\beta(t_1+w_1)}}=1+\frac{\frac{e^{\beta t_2}-1}{\beta t_2}}{\frac{e^{\beta(t_1+w_1)}-1}{\beta w_1}}.
\end{align*}

   Consider the following setup of parameters. 
Let $m$, $b_1$, and $t_1$ be fixed. Then, $w_1=\frac{m}{b_1}-t_1$ is also fixed. Let $t_2\rightarrow\infty$,  it follows that
\[M=\frac{e^{\beta t_2}-1}{\beta t_2}\rightarrow\infty,\]
since $\frac{e^{\beta t_2}-1}{\beta t_2}\rightarrow\infty$ as $t_2\rightarrow\infty$. 
Thus,  as we have  claimed,
\[\text{PoA}\ge1+\frac{\frac{e^{\beta t_2}-1}{\beta t_2}}{\frac{e^{\beta(t_1+w_1)}-1}{\beta w_1}}\rightarrow\infty.\]

\section{Proof of Proposition \ref{prop:switchingornot}}\label{appendix:proof_prop:switchingornot}

We first prove Proposition \ref{prop:switchingornot}.1 by giving a game instance $\mathcal{G}$ where a  nonstatioanry (switching) strategy can be more profitable than any deterministic stationary strategy of always choosing a single action.
Consider the constant action execution time model with $n=2$. Assume $b_1=b_2=\infty$.
 Since $\alpha>1$, the series
$\sum\limits_{n=1}^\infty n^{-\alpha}$
converges to $\zeta(\alpha)$, the Riemann zeta function evaluated at $\alpha$. For every $\epsilon>0$, there exists an integer $N$ such that 
\[0<N^{-\alpha}<\zeta(\alpha)- \sum\limits_{n=1}^{N-1}n^{-\alpha}<\epsilon.\]
Assume $t_2=Nt_1$ and $r_2=N^{\alpha}r_1-r_1$. Then,
\[
V(1, \boldsymbol{\tau})=r_1{t_1^{-\alpha}}\zeta(\alpha)
>\left(1-{N^{-\alpha}}\right)r_1{t_1^{-\alpha}}\zeta(\alpha)
=r_2{t_2^{-\alpha}}\zeta(\alpha) = V(2, \boldsymbol{\tau}).\]
Thus, the stationary strategy of always choosing action 1 is the optimal among  stationary strategies.
%We first consider the deterministic strategy of always choosing a single action. The best deterministic stationary strategy which generates the maximal possible accumulated reward is simply always choosing action 1. The resulting maximal possible reward is given by 
%\[\sum\limits_{n=1}^\infty r_1(nt_1)^{-\alpha}=\frac{r_1}{t_1^\alpha}\zeta(\alpha).\]

The following nonstatioanry (switching) strategy can result in a strictly better payoff: the agent chooses action 1 until time $T=Nt_1$ and chooses action 2 thereafter. The total utility under this strategy is
\begin{align*}
&\sum\limits_{n=1}^N r_1(nt_1)^{-\alpha}+\sum\limits_{n=2}^\infty r_2(nt_2)^{-\alpha}\\
    &\quad=r_1t_1^{-\alpha}\sum\limits_{n=1}^N n^{-\alpha}+(1-N^{-\alpha})r_1t_1^{-\alpha}\sum\limits_{n=2}^\infty n^{-\alpha}\\
    &\quad>r_1t_1^{-\alpha}\big[\zeta(\alpha)-\epsilon+(1-\epsilon)(\zeta(\alpha)-1)\big]\\
    &\quad=r_1t_1^{-\alpha}\big[(2-\epsilon)\zeta(\alpha)-1\big],
    \end{align*}
which is strictly larger than $V(1, \boldsymbol{\tau}) = r_1t_1^{-\alpha}\zeta(\alpha)$ if 
$\epsilon<1-{\zeta(\alpha)}^{-1}$.


We next prove Proposition \ref{prop:switchingornot}.2. 
We will only give a proof for the case when there are two actions. When there are more actions, the proof is similar.   Given $\boldsymbol{\mu}$, the sojourn time associated with the two actions $\tau_1$ and $\tau_2$ are then determined. Without loss of generality, we assume
\[\frac{r_1}{\tau_1(\bmu)}\ge\frac{r_2}{\tau_2(\bmu)}.\]
We will show that the deterministic stationary strategy of always choosing action 1 is the best response against $\bmu$.

We first define a sequence of positive constants: $\delta_k=\tau_1$ or $\tau_2$ for $k\ge1$.
Any switching strategy can be represented by the sequence $(\delta_k)_{k\in\mathbb{N}}$ where $\delta_k$ can be viewed as the $k$th choice of the strategy. Specifically, for the $k$th choice,  $\delta_k=\tau_1$ indicates the strategy under consideration chooses action 1 and $\delta_k=\tau_2$  indicates the strategy under consideration chooses action 2. Given $(\delta_k)_{k\in\mathbb{N}}$, define $\eta_k$, $k\in\mathbb{N}$,  as follows
\[\eta_k=\begin{cases}
    r_1,&\delta_k=\tau_1\\
    r_2,&\delta_k=\tau_2
\end{cases}\]
Let \[\theta_n=\sum_{k=1}^n\delta_k.\]
For any large enough $T$, there is a $N$ such that
\[\theta_N\le T<\theta_{N+1}.\]
To prove the desired result, we need the following facts which follow from 
%basic mathematical analysis knowledge. 
elementary facts.
When $0\leq\alpha<1$,
\begin{equation}\label{ineq_1-alpha}
    \sum_{k=1}^{N}\delta_k \theta_k^{-\alpha}\sim T^{-\alpha+1},
\end{equation}
and when $\alpha=1$,
\begin{equation}\label{ineq_log}
   \sum_{k=1}^{N}\delta_k\theta_k^{-1}\sim \log T.
\end{equation}
%It follows from basic mathematical analysis knowledge that \eqref{ineq_1-alpha} and \eqref{ineq_log} hold. Alternatively,  from Figure \ref{fig:alpha} we see that as $T\rightarrow\infty$, the sum of areas of the shadowed rectangles converge to the integral of $x^{-\alpha}$ over the interval $[0,T]$ when $0<\alpha\le1$. 


Now assume $0\leq\alpha<1$; the discussion for $\alpha=1$ is similar. For any switching strategy represented by $(\delta_k)_{k\in\mathbb{N}}$ and $(\eta_k)_{k\in\mathbb{N}}$, the total utility is
\[\sum_{k=1}^{N}\eta_k \theta_k^{-\alpha}.\]
Note that $\frac{\eta_k}{\delta_k}=\frac{r_1}{\tau_1}$ or $\frac{r_2}{\tau_2}$. Hence,
\[\sum_{k=1}^{N}\eta_k \theta_k^{-\alpha}=\sum_{k=1}^{N}\frac{\eta_k}{\delta_k}\delta_k \theta_k^{-\alpha}\le \frac{r_1}{\tau_1}\sum_{k=1}^{N}\delta_k \theta_k^{-\alpha}\sim\frac{r_1}{\tau_1}T^{-\alpha+1}.\]
The reward of always choosing action 1 is $V_1(T)\sim\frac{r_1}{\tau_1}T^{-\alpha+1}$ by \eqref{eq:reward_VT}. Thus, always choosing action 1 cannot be asymptotically worse than any nonstationary  (switching) strategy. 

Now if there are $n>2$ actions and multiple actions have the largest reward rate, i.e.,  
\[\frac{r_1}{\tau_1(\bmu)}=\cdots=\frac{r_j}{\tau_j(\bmu)}>\frac{r_{j+1}}{\tau_{j+1}(\bmu)}\geq \cdots\geq \frac{r_{n}}{\tau_n(\bmu)}.\]
From the proof for the two-action case, it is clear that any randomized stationary strategy which randomizes over the set of actions $\{1,\cdots,j\}$ and any deterministic stationary strategy which always chooses one action from $\{1,\cdots,j\}$ are  best responses against the agent mass distribution $\bmu$.


