exist $b>0$ such that,
\begin{equation}
    b<\gamma_1\frac{
\mu_1^\dagger}{t_1}+\gamma_2\frac
{m-\mu_1^\dagger}{t_2}.\label{condition:unstable_2_b}
\end{equation}
