\end{aligned}
\]
where the second equality follows from \eqref{condition:unstable_2_r} and the last inequality follows from \eqref{condition:unstable_1a} since
\[\gamma_1\tau_2(\mu_1^\dagger)-\gamma_2\tau_1(\mu_1^\dagger)=\gamma_1(t_2+\gamma_2w(\mu_1^\dagger))-\gamma_2(t_1+\gamma_2w(\mu_1^\dagger))=\gamma_1t_2-\gamma_2t_1>0,\]
