    \centering
    \includegraphics[width=\textwidth]{./figs/format.png}
    \caption{Comparison of average flip rates across five presentation formats. Each heatmap shows the average flip rate based on different combinations of agreeing and disagreeing peers. The x-axis represents the number of agreeing agents, and the y-axis represents the number of disagreeing agents. Higher flip rates are shown in red, while lower rates are shown in blue.}
    \label{fig:format}
\end{figure*}

\begin{figure}[t]
