%Let \( \mathcal{K} : L^2([-1,1]) \to L^2([-1,1]) \) be the integral operator defined by
%\begin{equation}
%(\mathcal{K}f)(y) = \int_{} e^{i \gamma x y / 4} f(x) \, dx,
%\end{equation}
