%     \gamma_{u,n} \approx \frac{P_{u.n}|\boldsymbol{h}_u ^H \boldsymbol{f}_{u,n} |^2}{\sigma_{\omega}^2}
% \label{eq:approximate_SINR}
% \end{equation}


