%     c_{qu,n} = \int_0^{dt} \dot{s}_{u,n}(t-\tau_{u,n}) \dot{s}^*_{q,n}(t - \hat{\tau}_{q,n}) e^{j2\pi (\mu_{u,n} - \hat{\mu}_{q,n}) t} dt 
% \end{equation}
where 
%$\alpha_{uq,n} =   \beta_{u,n} \boldsymbol{a}^H (\varphi_u) \boldsymbol{f}_{q,n}, u = 1, \cdots, U$, 
the second term in \eqref{eq:separated_echo} is the clutter for estimating the desired $\varphi_q$,  and the noise 
% \begin{equation}
% \small
% \tilde{\boldsymbol{\omega}}_n(t) = \int_0^{dt} \boldsymbol{\omega}_n(t) \dot{s}^*_{q,n}(t - \hat{\tau}_{q,n}) e^{-j2\pi \hat{\mu}_{q,n} t} dt     
% \end{equation}
$\tilde{\boldsymbol{\omega}}_n(t)$ follows $\mathcal{CN}(\boldsymbol{0}, \sigma_{\omega}^2/\Delta T \mathbf{I})$. Note that this clutter, which indicates multi-user interference, is different from fixed clutter in the environment. The cross-correlation of the baseband waveform of different users is neglected as they are uncorrelated for a large $\Delta T$.  
% Let us denote the scalar coefficient in \eqref{eq:separated_echo} as
% $\alpha_{uq,n} =   \beta_{u,n} \boldsymbol{a}^H (\varphi_u) \boldsymbol{f}_{q,n}, u = 1, \cdots, U$. Then, $\boldsymbol{\eta}_{q,n}$ is simplified to 
% \begin{equation} 
% \small
%     \boldsymbol{\eta}_{q,n} = \sqrt{P_{q,n}}\alpha_{qq,n} \boldsymbol{a}(\varphi_q) + \sqrt{P_{q,n}} \sum_{u=1,u\neq q}^{U}  \alpha_{uq,n} \boldsymbol{a}(\varphi_u) + \tilde{\boldsymbol{\omega}}_n(t) .
% \end{equation}

The clutter in the processed signal impacts the estimation performance. This work considers a large antenna array at the BS and also assumes that users are separated enough. In this case, $\alpha_{uq,n}$ approximates to 0. Thus, the clutter has a limited effect on the estimation performance. By estimating the AoD of each user individually, the AoD and user association problem can be solved.

The AoD can be estimated as
\begin{equation}
\small
    \hat{\varphi}_{q,n} = \arg \underset{\theta}{\max} ~~ \boldsymbol{a}^H(\theta) \boldsymbol{\eta}_{q,n} \boldsymbol{\eta}^H_{q,n} \boldsymbol{a}(\theta) .
\label{eq:aod_estimate}
\end{equation}
Specifically, the CRLB of the maximum likelihood estimate of $\varphi_{q,n}$ when $\alpha_{uq,n}=0$ can be obtained as \cite{liu_crb_2022}
% \begin{equation}
% \small
%     \sigma_{{\varphi}_{q,n}}^2 \ge \frac{ \sigma_{\omega}^2 / | \alpha_{q,n}|^2}{2 \Delta T\left(\left\|\dot{\dot{\boldsymbol{a}}}(\varphi)\right\|^2 + \boldsymbol{a}^H(\varphi)\dot{\dot{\boldsymbol{a}}}(\varphi) +  \dot{\dot{\boldsymbol{a}}}^H(\varphi)\boldsymbol{a}(\varphi) \right)} ,
% \label{eq:crlb}
% \end{equation}
\begin{equation}
\small
    \sigma_{{\varphi}_{q,n}}^2 \ge \frac{ \sigma_{\omega}^2 / (P_{q,n}| \boldsymbol{a}^H (\varphi_{q,n}) \boldsymbol{f}_{q,n}|^2)}{2 \Delta T\left(\left\|\dot{\dot{\boldsymbol{a}}}(\varphi)\right\|^2 + \boldsymbol{a}^H(\varphi)\dot{\dot{\boldsymbol{a}}}(\varphi) +  \dot{\dot{\boldsymbol{a}}}^H(\varphi)\boldsymbol{a}(\varphi) \right)} ,
\label{eq:crlb}
\end{equation}
where $\dot{\dot{\boldsymbol{a}}}(\varphi) = \frac{\partial  \boldsymbol{a}^2(\varphi)}{\partial \varphi^2}$ is the second derivative.

As indicated by \eqref{eq:crlb}, the performance of estimating the AoD of user $q$ is affected by the gain achieved in the transmit mode, i.e., $|\boldsymbol{a}^H (\varphi_q) \boldsymbol{f}_{q,n}|^2$. This gain decreases due to the beam coverage when the target user is not in the center of the beam. This aligns with the result obtained in \cite{MugenPeng2023}. Meanwhile, the estimation precision of the AoD implies the quality of the allocated communication beam.


%The cross-correlation between the signals of different users also impacts the performance. This work considers that transmitted signals of different users are uncorrelated. As such, when $\Delta T$ is large, the echoes from the other users can be omitted. By estimating the AoD of each user individually, the AoD and user association problem can be solved.



\section{Beam Management Problem}
%In the ISAC scheme, the BS needs to satisfy both the communications and sensing requirements. 
%The beamforming vector $\boldsymbol{f}$ applied at the BS is supposed to direct the signal to each communication users, while the reflected signal captured by the sensing receiver is able to be used for sensing purposes. This paper considers the sensing-assisted communication scheme. The idea is that the BS uses the received echo for the estimation AoDs of different users and performs beam management.

This work focuses on dynamic beam management for resolving beam drift in sensing-assisted communication systems. It updates beams without user feedback but only with the obtained sensing information.
The result presented above shows that the CRLB increases when the beam is not directed to the target. Hence, reusing communication beams for sensing \cite{deep_rl_liu_2024_wcnc, Chen2024} is prone to induce beam failure when the communication beam drifts. A wide sensing FoV helps relieve the problem. To do so, the authors in \cite{zhang_multibeam_2019} proposed a multi-beam ISAC scheme that generates one time-invariant communication beam and one fast-varying sensing beam sweeping the area of interest during a channel coherence time. However, this requires the transmitter to switch the beamforming coefficients quickly, decreasing energy efficiency. Instead, we consider using multiple beams simultaneously for sensing to broaden the FoV.

In this section, we first describe the objective function of the sensing-assisted communication system and then propose an AoD-based method for managing multi-beams.    

\subsection{Objective Function}
% \subsubsection{Traffic Model}
% Each user’s traffic follows an independent Bernoulli process with probability $Pr^u$ for generating packets in every time TTI $n$, which can be written as
% \begin{equation}
%    \text{Tr}_{u,n} = \text{Bernoulli}(Pr^u)
% \end{equation}
% where $\text{Tr}_{u,n}$ is 0 or 1 denoting if a packet is generated for user $u$. 
% Considering the traffic model, a user is supposed to be a CU when there is data packet generated. 

We consider $U$ data buffers at the BS. Let $[B_{1,0}, \cdots, B_{U,0}]$ be the vector of the number of data packets generated at the beginning of a frame for each user, where $B_{u,0} \sim \mathbb{B}(N, \mathrm{Pr}_u)$ and $\mathbb{B}$ denotes the Binomial distribution. The total number of packets at the beginning of the frame is defined as $B_{tot} = \sum_{u=1}^{U} B_{u,0}$. A frame lasts for $N$ TTIs. Accordingly, the number of packets remaining in the buffer of user $u$ at TTI $n$ is denoted as $B_{u,n}$. Specifically, for a TTI, we consider that the packets are successfully transmitted when the communication rate is larger than a threshold $c$, that is, 
% $\log (1 + \gamma_{u,n}) \geq c$.
\begin{equation}
    \small \log (1 + \gamma_{u,n}) \geq c. 
    \label{eq:communication_criterion}
\end{equation}


The ultimate goal is to maximize the probability of successful transmission or equivalently minimize the remaining packets in the buffer at the end of the frame. The objective function is written as
\begin{equation}
\small
    \text{minimize} \sum_{u=1}^{U} B_{u,N} .
\label{eq:final_goal}
\end{equation}
The resources that the BS needs to dynamically manage during each TTI include beams and power for each user. To achieve the objective in \eqref{eq:final_goal}, the BS is supposed to update the beams when they are drifting. 

\subsection{AoD-Based Method}
We propose a scheme in which the BS groups users to CU for communication and SU for updating their AoD estimates dynamically at each TTI. The challenge is how the BS determines which mode each user is in. Ideally, the type of each user should be decided according to their estimation error. However, this requires the knowledge of true AoDs. Since the precision of AoD estimation implies the quality of the communication beam, we use this information for resource management without needing specific AoD estimation.





\subsubsection{User and Beam allocation} Let $\lambda_u$ denote the user type of the $u$-th user, i.e., $1$ represents a CU, 0 represents an SU. It is decided according to the estimation precision, i.e., 
\begin{equation}
\small \lambda_u = \boldsymbol{1}_{(\sigma_{{\varphi}_{u}} \le th)}  ,
\label{eq:sensing_criterion}
\end{equation}
where $\boldsymbol{1}$ denotes the indicator function, $th$ is a predefined threshold, and $\sigma_{{\varphi}_{u,n}}$ is the standard deviation of the estimation error calculated from the CRLB.
\begin{figure}
    \centering
    \includegraphics[width=.38\textwidth]{figs/protocol.png}
    \caption{Sensing-Assisted Communication Protocol}
    \label{fig:protocol}
\end{figure}

The beam for a CU is set according to AoD estimate, that is, $\boldsymbol{f}_{u,n} = [\tilde{\mathbf{F}}]_{:,\hat{\varphi}'_{u,n-1}}$. The prime sign denotes that the estimated angles are approximated to the grid such that the beam is selected from the DFT codebook.
Accordingly, the beam for an SU is 
% \begin{equation}
$\boldsymbol{f}_{u,n} =  \sum_{\hat{\varphi}'_{u,n-1} \in \{ \hat{\varphi}_{u,n-1} \pm \sigma_{{\varphi}_{u,n-1} \}} }[\tilde{\mathbf{F}}]_{:,\hat{\varphi}'_{u,n-1}}$.
% \end{equation}


It is noted that calculating CRLB requires genie AoD. The AoD-based method uses the approximated CRLB by substituting AoD estimates. Meanwhile, determining user type based on AoD estimation error and allocating beams according to CRLB is referred to as \emph{AoD-Genie} method. We consider it as an upper bound, which is evaluated in Section \ref{sec:simulation}.

The dynamic beam allocation protocol is exemplified in Fig. \ref{fig:protocol}. At the $n$-th TTI, the user beams are selected based on the echoes received during the $(n-1)$-th TTI. The $U$-th user is apart from the center of beam $\boldsymbol{f}_{U,n}$. Then, at TTI $n$, the BS allocates multiple beams for user $U$ to obtain a better estimation precision. 



%\roa{Equation 15 provides a useful performance bound on the estimation of AoD - which is nice to have. Its relationship to the problem of showing why multiple beams are needed to sensing is still a bit unclear to me. }






\subsubsection{Power allocation}\label{sec:power_allocation}
After the user type and beams during TTI $n$ are determined, the BS calculates the power allocation. 
The requirement of communication in \eqref{eq:communication_criterion} can be simplified to $\xi_c = \frac{|\boldsymbol{h}_u ^H \boldsymbol{f}_{u,n} |^2}{\sigma_{\omega}^2} \ge \frac{2^c-1}{P} \triangleq \iota_c$, 
and that of sensing in \eqref{eq:sensing_criterion} is simplified to $\xi_s = \frac{ \beta^2_{u,n} \big|\boldsymbol{a}^H (\varphi_q) \boldsymbol{f}_{u,n}\big|^2 \Delta T }{\sigma_{\omega}^2} \ge \frac{th^2}{P}\triangleq \iota_s$, where $\iota_s, \iota_c$ are the threshold for satisfying the requirements of sensing and communication respectively\footnote{The power for SU is equally distributed to the multiple beams. Optimizing the power to different beams will be studied in future work}.
Within a TTI, the objective function concerning power allocation is given by
\begin{equation}
\small
    \arg \max_{P_u} \sum _{u=1}^U \boldsymbol{1}_{\lambda_u P_u \frac{\xi_c}{\iota_{c}} + (1-\lambda_u)P_u \frac{\xi_s}{\iota_{s}} \ge 1} .
\end{equation}
This recasts the problem as maximizing the number of users whose signal strength is larger than a threshold, which is solved by the water-filling algorithm \cite{he_water-filling_2013}.
Note that $\xi_s$ and $\xi_c$ are approximated using the estimates of AoD in  \eqref{eq:aod_estimate} and of distance in  \eqref{eq:delay-doppler}.


\section{DRL-assisted Beam Management}
DRL is a technique where an agent employs deep neural networks to map observations to optimal actions. Proximal
policy optimization (PPO) \cite{ppo_2017} is a popular DRL algorithm that
prevents the policy from having a large update and performs
comparable or better than other DRL algorithms. 
In this paper, we use the PPO algorithm \cite{ppo_2017} to train the agent, i.e., BS. The BS observes the environment and allocates resources for all users. However, the action space is hybrid, containing discrete actions for user type and beam, and continuous actions for power level. We propose to simplify the agent by only taking discrete actions. Once the actions are set, the power allocation is calculated as in Section \ref{sec:power_allocation}.

Details on observation, actions, and reward functions are:

\emph{Observation:} 
The estimation performance is a function of the beamforming gain $|\boldsymbol{a}^H(\varphi_q) \boldsymbol{f}_{q,n}|^2$, as shown in  \eqref{eq:crlb}. This beamforming gain can be obtained at the BS by calculating the beamforming output 
\begin{equation}
\small
\boldsymbol{b}_{u,n} = \mathrm{E}\{|\boldsymbol{f}_{u,n}^H \boldsymbol{Y}_n|^2 \} 
%=  &\boldsymbol{f}_{u,n}^H  \sum_{u=1}^{U} \beta_{u}\boldsymbol{a}(\varphi_u^1) \boldsymbol{a}^H(\varphi_u^1) \sum_{u=1}^U \sqrt{P_{u,n}}\boldsymbol{f}_{u,n}s_{u,n} \\ 
\approx \beta_u^2 P_{u,n} |\boldsymbol{f}_{u,n}^H \boldsymbol{a}({\varphi_u})|^4  +
%|\boldsymbol{I}_{inter-user}|^2 + 
\sigma_n^2 ,
\end{equation}
where $\boldsymbol{Y}_n = [\boldsymbol{y}_{n}(1), \cdots, \boldsymbol{y}_n(\Delta T)]$ is the received echo within TTI $n$ and the expectation is taken over time. 
This is equivalent to measuring the power in the transmitted direction, which implies the beam allocation quality.

The state of the DRL model is the number of packets remaining in the buffer, the total number of packets for the frame, and the beamforming output with respect to the transmitted beams of each user. The state is written as
\begin{equation}
\begin{aligned}
    s_n  = \{&[B_{1}, \cdots, B_{U}],  B_{tot}, [\boldsymbol{b}_{1,n-2}, \cdots, \boldsymbol{b}_{U,n-2}], \\&[\boldsymbol{b}_{1,n-1}, \cdots, \boldsymbol{b}_{U,n-1}], [\boldsymbol{b}_{1,n}, \cdots, \boldsymbol{b}_{U,n}]\} \in \mathcal{S}.
\end{aligned}
\end{equation}
The BS restores the beamforming output of the past 3 TTIs. The historical beamforming output helps the BS learn the user's moving direction.



\emph{Action:}
The agent action is to determine user type and beams, which is given by
\begin{equation}
   a_n =   \{[\lambda_1, \cdots, \lambda_U], [\mathcal{C}_{1}, \cdots, \mathcal{C}_{U}]\} \in \mathcal{A} .
\end{equation}
where $\lambda_u$ is user type of the $u$-th user, and $\mathcal{C}_{u}$ denotes the beam indices that are allocated for user $u$.
The beamforming weight is computed as $\boldsymbol{f}_u = \sum_{i\in\mathcal{C}_u} \tilde{\mathbf{F}}_{i,:}$.


It is difficult to determine the action space dimension for $\mathcal{A}$ because each user has one or multiple beams depending on its type. One option is to assign every beam to one of the $U$ users or stay idle. This yields the action space dimension of $N_t^{U+1}$. In the mmWave spectrum, the number of beams $N_t$ is high leading that the convergence of the learning algorithm is hardly guaranteed, and large memory is required for computation. We shrink the action space as follows.
For the user $u$, there are two cases depending on the user type in the $(n-1)$-th TTI.

Case 1: $\lambda_{u,n-1} = 1$, and beam index is $\mathcal{C}_{u, n-1}$
\begin{itemize}
    \item $n$ TTI, $\lambda_{u,n} = 1$, the beam $\mathcal{C}_{u, n} = \mathcal{C}_{u, n-1}$
   \item $n$ TTI, $\lambda_{u,n} = 0$, the beam can be 
   \begin{itemize}
      \item $\mathcal{C}_{u, n} = \mathcal{C}_{u, n-1} + [-2,-1,0]$
     \item $\mathcal{C}_{u, n} = \mathcal{C}_{u, n-1} + [0, 1, 2]$
    \end{itemize}
\end{itemize}


Case 2: $\lambda_{u,n-1} = 0$, and beam index is $\mathcal{C}_{u, n-1}$ 
\begin{itemize}
   \item $n$ TTI, $\lambda_{u,n} = 1$, the beam $\mathcal{C}_{u, n}$ is obtained from the estimation result
   \item $n$ TTI, $\lambda_{u,n} = 0$, the beam $\mathcal{C}_{u, n}$ needs to cover more area
    \begin{itemize}
      \item $\mathcal{C}_{u, n} = \min(\mathcal{C}_{u, n-1}) + [-2,-1,0]$
      \item $\mathcal{C}_{u, n} = \max(\mathcal{C}_{u, n-1}) + [0, 1, 2]$
    \end{itemize}
\end{itemize}
When a user is a sensing user, the BS allocates some adjacent beams of its previous TTIs to enlarge its sweeping area. 
As a result, the action space dimension decreases to $3^U$.


\emph{Reward:}
The reward of each step is given by
\begin{equation}
\small
r^c = \left(1 + \exp \Big(\frac{B_{tot} - \sum_{u=1}^{U}B_u }{B_{tot}}\Big) \right) \sum_{u=1}^{U} \lambda_u \boldsymbol{1}_{\log(1+\gamma_{u,n}) >c} ,
\end{equation} 
where the first multiplicative term is set to encourage the agent to transmit more packets.
Even though the sensing criterion is not included in the reward function, the sensing performance is implicitly exhibited in the long term reward because it will affect the subsequent communications. 

The DRL-assisted method is initialized with that the agent knows the best beams towards each user and receives the echoes as the initial observation. In each step, the agent observes the state to select the action based on the policy. The policy network consists of 2 fully connected layers with 64 units which are also shared with the critic network. PPO algorithm trains the policy by using a clip function in the surrogate objective function to prevent the policy from having a large variance \cite{ppo_2017}. The clipping parameter is set to 0.2. 

