\begin{restatable}{observation}{nothorizontallysandwiched}
    \label{lem:not-horizontally-sandwiched}
    A point~$x$ of~$T$ at height~$h$ cannot be surrounded by two points $x_1$ and~$x_2$ at height~$h$ of another branch.
\end{restatable}

\begin{restatable}{observation}{noleafabovehorizontal}
    \label{lem:no-leaf-above-horizontal}
    In the drawing of a tree~$T$, no leaves are positioned vertically above a horizontal segment.
\end{restatable}

\noindent
We now show that ParkView satisfies properties (i)--(iii).

\begin{restatable}{lemma}{propertyproof}
    \label{lem:hedges-disjoint}
	Hedges in ParkView satisfy property (i).
\end{restatable}
\begin{proofsketch}
    For each height in our drawing, we consider a horizontal line at that height. This line intersects a number of points of~$T$, which belong to branches. By \autoref{lem:not-horizontally-sandwiched}, these branches partition the line into disjoint intervals that ``belong'' to each branch.
    We then show that using this procedure, each point in a hedge~$H_\pi$ ``belongs'' to the branch~$B_\pi$. As each point ``belongs'' only to a single branch, it follows that no point can be in more than one hedge.
\end{proofsketch}

\begin{restatable}{lemma}{yetanotherproperty}
    \label{lem:no-multiple-parents}
    Hedges in ParkView satisfy property (ii).
\end{restatable}
\begin{proofsketch}  
    For any hedge~$H_\pi$, we can show that (a) it needs to have a point of~$T$ on the top, which is adjacent to some tree bar in a parent hedge, and (b) any other bars adjacent to the top of~$H_\pi$ need to be part to the same parent hedge.
\end{proofsketch}

\begin{restatable}{lemma}{anotherpropertyproof}
    \label{lem:no-child-on-longest-bar}
	Hedges in ParkView satisfy property (iii).
\end{restatable}
\begin{proofsketch}
    Let $b$ be a longest bar in a hedge~$H_\pi$. We can show that $b$ is a tree bar, because if it were a filler, this would violate \autoref{lem:no-leaf-above-horizontal}. We prove a key property: a tree bar that is a longest bar of its hedge has a leaf of~$T$ on its bottom. Hence, $b$ has such a leaf. Now assume that there is another hedge~$H_\rho$ adjacent to the bottom of~$b$. Then on the top of~$H_\rho$, there has to be a point via which $H_\rho$ connects to the rest of~$T$. As each hedge can have at most one parent (\autoref{lem:no-multiple-parents}) this connection is via a bar~$b'$ of~$H_\pi$. However, then~$b'$ is a longest tree bar. This contradicts our key property that $b'$, being a longest tree bar, has a leaf on its bottom.
\end{proofsketch}

\noindent
We now show that any set of histograms satisfying (i)--(iii) is 3-colorable, from which it follows that our hedges are 3-colorable.

\begin{figure}[b]
    \centering
    \includegraphics{figures/3-colorability.pdf}
    \caption{A set of histograms where $P$ is the parent of $G$. The histogram $P$ has a bar~$b$ whose bottom lies below the top of $G$.}
    \label{fig:parent-histogram}
\end{figure}

\begin{theorem}
    \label{thm:3-colorable}
    Any set~$C$ of histograms that satisfies properties (i)--(iii) is 3-colorable.
\end{theorem}
\begin{proof}
    We prove by induction on $n = |C|$.
    For $n = 1$, the theorem trivially holds.
    Now assume that $C$ contains $n+1$ histograms, and let $G$ be a histogram whose top is lowest.
    As the top of any other histogram~$G'$ cannot lie below the top of~$G$, no histogram in~$C$ is adjacent to the bottom side of any bar of~$G$.
    Similarly, there can be only at most one histogram in~$C$ adjacent to the left of~$G$, and there can be only at most one histogram in~$C$ to the right of~$G$.
    Lastly, $G$ can have at most one parent by property~(i), so $G$ has at most three adjacent histograms.

    The set of histograms $C' \coloneqq C \setminus \{G\}$ still satisfies properties (i)--(iii) and has size~$n$.
    Assume (induction hypothesis) that $C'$ is 3-colorable and fix a 3-coloring~$c_1$ for~$C'$. We edit~$c_1$ into a 3-coloring for~$C$.
    If the at most three histograms adjacent to~$G$ use fewer than three colors, we can simply use the third color for~$G$ to obtain a 3-coloring for~$C$.
    Otherwise, denote by $L$ and~$R$ the histograms adjacent to the left and right side of~$G$, and let~$P$ be the parent of~$G$.
    Since $P$, $L$, and~$R$ all have different colors, we can assume without loss of generality that $c_1$ assigns colors 1, 2, and~3 to~$P$, $L$, and~$R$, respectively.
    By property (iii) there is no histogram adjacent to the bottom of a longest bar of~$P$, so we know that $P$ extends below the top of~$G$.
    Thus, $P$ extends below the top of~$G$ either to the left or to the right of~$G$.
    Without loss of generality, assume it extends left of~$G$ and call the rightmost such extending bar~$b$ (\autoref{fig:parent-histogram}).

    Consider the descendants~$C''$ of~$P$ that lie to the left of~$G$ and to the right of~$b$.
    Since $L$ is contained in $C''$, the set $C''$ is nonempty.
    This means that the set $C \setminus C''$ is again a set of histograms that satisfies (i)--(iii) and has size at most $n$, and is hence 3-colorable by the induction hypothesis.
    Let $c_2$ be a 3-coloring of $C \setminus C''$ such that without loss of generality $P$ has color~1 and $G$ has color~3.
    We now define a coloring $c_3$ for~$C$ where the histograms of $C \setminus C''$ take its color from~$c_2$, and the histograms in $C''$ take their color from~$c_1$.

    Note that $G$ and $P$ are the only two histograms of $C \setminus C''$ that are adjacent to histograms in~$C''$.
    So, one of four cases applies to any two adjacent histograms of $C$: (a) both lie in $C \setminus C''$, (b) both lie in $C''$, (c) one is $P$ and the other lies in $C''$ or (d) one is $G$ and the other lies in $C''$ (i.e., the other is $L$).
    For $c_3$ to be a $3$-coloring, it suffices to show that in each case, $c_3$ assigns them distinct colors.
    In case (a), $c_3$ assigns the same distinct colors as $c_1$.
    In case (b), $c_3$ assigns the same distinct colors as $c_2$.
    In case (c), $P$ has color $1$ in both $c_1$ and $c_2$, so $c_3$ again assigns the same distinct colors as $c_2$.
    In case (d), $L$ has color 2 and $G$ has color 3.
\end{proof}

\noindent
Since a hedge is a specific histogram, and our drawing satisfies properties (i)--(iii), we now know that our set of hedges is 3-colorable.

\section{Computing ParkView}\label{sec:algorithms}
ParkView receives as input two ordered merge trees $T$ and $T'$, and a monotone interleaving $(\alpha, \beta)$ between them.
We construct a ParkView visualization using the following four step process:
\begin{enumerate}[noitemsep]
    \item Compute heavy path-branch decompositions for $\alpha$ and $\beta$.
    \item Draw the trees $T$ and $T'$ by drawing their path decomposition.
    \item Draw the branch decompositions as hedges behind the trees, and draw the corresponding active paths on top of the trees.
    \item Color the hedges in both trees, and correspondingly color their active paths in the other tree.
\end{enumerate}
\noindent
The pseudocode we provide in this section is high-level; for details we refer the reader to our implementation\footref{fn:code}.

\cparagraph{Heavy path-branch decompositions.}
We aim to compute a path-branch decomposition with few branch components.
Recall that branches follow uniquely from paths; therefore, our only concern is computing a path decomposition.
As explained in \autoref{sec:path-branch-decomposition}, decomposing a tree into paths is equivalent to choosing at each internal vertex $v$ a down edge that connects to the up edge of $v$ via a path.
In \autoref{sec:heavy-path-branch-decomposition} we define a weight on the down edges of a vertex, and argue that choosing at every vertex the down edge of maximum weight is optimal (\autoref{thm:heavy-path-branch}): the resulting path decomposition minimizes both the total number and the maximum number of branch components.
\autoref{alg:greedy-path-decomposition} computes such a path decomposition in a recursive manner.
In ParkView, when multiple down edges at a vertex have maximum weight, we choose the down edge whose corresponding active path has the lowest start point.

The running time of \autoref{alg:greedy-path-decomposition} is linear in the number of leaves of $T$ and $T'$.
We can for example represent the shift map as an array such that the image under $\alpha$ of a vertex in $T$ can be determined in constant time.
Then by iteratively traversing $T$ from each leaf to its root (and stopping a traversal when encountering an edge that has been traversed before), one can in linear time determine the weights of the edges in $T'$.
After precomputing these edge weights, the recursion then takes linear time.


\begin{algorithm}[tbh]
\Input{Merge trees $T$ and $T'$ and a shift map $\alpha$ from $T$ to $T'$.}
\Output{A heavy path-branch decomposition of $\alpha$.}
\BlankLine

for an edge $e$ of $T'$, let $B_e$ be the part of~$T$ that $\alpha$ maps to the interior of~$e$\;
by simultaneously traversing the trees---following shift map~$\alpha$---pre-compute values $|B_e|$ for each edge~$e$ of $T'$\;

\BlankLine
\SetKwFunction{decompose}{decompose}
\SetKwProg{func}{Function}{}{}
\func{\decompose{$v$}}{
    \If{$v$ is a leaf} {
        \Return $\{ \text{ path from } v \text{ traversing its up edge } \}$\;
    } \Else {
        initialize empty path decomposition $\Pi \gets \emptyset$\;
        \For {child $c$ of $v$} {
            add $\decompose{c}$ to $\Pi$\;
        }
        let $e$ be a down edge at $v$ with $|B_e|$ maximum\;
        let $\pi \in \Pi$ be the path that traverses $e$\;
        extend $\pi$ along the up edge of $v$\;
        \Return $\Pi$\;
    }
}{}
\BlankLine

\Return \decompose{\text{\upshape root of }$T'$}\;

\caption{Heavy Path-Branch Decomposition}
\label{alg:greedy-path-decomposition}
\end{algorithm}

\cparagraph{Drawing and coloring.}
After the path-branch decompositions of the two shift maps have been computed, we first draw the ordered merge trees as described in \autoref{sec:drawing-merge-trees}.
Recall that we draw ordered merge trees rectilinearly by drawing each path in the corresponding path decomposition vertically in its own column.
We make columns with an active path in them wider to emphasize important parts of the tree and improve the scalability of the visualization.
We draw the branches and their corresponding active paths incrementally in a top-down fashion.
\autoref{alg:hedges} describes this drawing algorithm, which simultaneously colors the hedges and corresponding active paths. 
As a last step, we create grid lines and space them by some factor of the interleaving height $\delta$.
We draw the grid as black lines with high transparency on top of the hedges, but behind the tree.

