%\end{remark}

\begin{definition}\label{def-bisimulation}
Let $M = (S,T,\{r_i \mid i \in \mathcal{A}\},v)$ be a KLTS.
A binary equivalence relation $B$ on $S$ is a bisimulation iff whenever $(s,t) \in B$ then:
\begin{enumerate}
    \item $v(s) = v(t)$;
    \item if $(s,a,s') \in T$ then $\exists t' \ldotp (t,a,t') \in T$ and $(s',t') \in B$;
%    \item if $(s,s') \in l(r_i(s))$ for some $i \in \mathcal{A}$ then $\exists t' \ldotp (t,t') \in l(r_i(t))$ and $(s',t') \in B$.
\item there exists a binary equivalence relation $\mathcal{B}_{st}$ between the worlds of the Kripke models $(2^{At},\{r_i(s) \mid i \in \mathcal{A}\},\mathit{id})$ pointed at $v(s)$ and $(2^{At},\{r_i(t) \mid i \in \mathcal{A}\},id)$ pointed at $ v(t)$, such that $(v(s),v(t)) \in \mathcal{B}_{st}$ and for any $X,Y \in 2^{At}$, whenever $(X,Y) \in \mathcal{B}_{st}$ then:
\begin{itemize}
    \item $X = Y$;
    \item if $(X,X') \in r_i(s)$ for $i \in \mathcal{A}$, then $\exists Y' \ldotp (Y,Y') \in r_i(t)$ and $(X',Y') \in \mathcal{B}_{st}$.
\end{itemize}
\end{enumerate}
\end{definition}

Note that conditions $1.$ and $3.$ resemble the definition of modal bisimulation for Kripke models~\cite{blackburn2002modal}, while condition $2.$ characterizes the strong bisimulation for LTSs~\cite{HML}.
Two states $s$ and $s'$ are bisimilar, denoted 
$s \sim s'$, if and only if there exists a bisimulation $B$ such that $(s,s') \in B$.
The correspondence theorem relates bisimilar states and equivalent states whenever the KLTS is image finite, i.e., for all states and actions, the image of $s$ (under any accessibility relation) and the image of $s, \pi$ (under the transition relation) are finite.

\begin{theorem}\label{main_thm}
For any image-finite KLTS, $\sim$ coincides with $\equiv$.
\end{theorem}

