\begin{itemize}
\item Base: Since $v_1(s_{01}) = v_2(s_{02})$, $M_{1s_{01}}, v_1(s_{01}) \models_{\mathrm{K}} p$ iff $M_{2s_{02}}, v_2(s_{02}) \models_{\mathrm{K}} p$.
