\section{Proofs of Statements About Digraphs and Homomorphisms}
\label{appendix:basic-digraphs}
We first define a few basic concepts:

\begin{definition}\hspace{0cm}
    \begin{itemize}
        \item Let $W = (a_0, r_0, a_1, r_1, \ldots, a_n, r_{n}, a_{n+1})$ be an oriented walk. The inverse of $W$ is  \begin{align*}
        -W \coloneqq (a_{n+1}, r_n' , a_n , \ldots, r_1', a_1, r_0', a_0)
        \end{align*} where $r_i'$ is the opposite of $r_i$, so $r_i' \coloneqq  \begin{cases}
            + \If r_i = -\\
            - \If r_i = +
        \end{cases}$.

        \item For oriented walks $W = (a_0, r_0, \ldots, a_{n+1})$ and $W' = (b_0, s_0, \ldots, b_{n+1})$ with $a_{n+1} = b_0$ we can define the composition of $W$ and $W'$ as \begin{align*}
        W \circ W' = (a_0, r_0, \ldots, a_{n+1} = b_0 , s_0, \ldots, b_{n+1}).
    \end{align*}
    \end{itemize}
\end{definition}


We can now prove:
\girthProp*
\proof 
The left-to-right direction follows immediately from Lemma \ref{girth-lemma}, since every cycle of positive net length is a closed oriented walk. 

Let us now prove the other direction. We assume $n \mid \gamma(A)$. 
By Lemma \ref{girth-lemma} it suffices to show $\gamma(A) \mid l(W)$ for every closed oriented walk $W= (a_0, r_0, a_1, r_1, \ldots, a_{n-1}, r_{n-1}, a_{n})$ in $A$. To do that we use strong induction over $n$, the length of the walk (not the net length). We have two cases:
\begin{itemize}
    \item Assume $W$ is an oriented cycle. If $l(W) = 0$ then trivially $\gamma(A) \mid l(W)$. If $l(W)>0$ then by definition $\gamma(A) \mid l(W)$. Lastly, if $l(W)<0$ then $l(-W)>0$ so $-W$ has positive net length. Then $\gamma(A) \mid l(-W)$ but $l(-W) = -l(W)$ so $\gamma(A) \mid l(W)$.

    \item Assume $W$ is not an oriented cycle. Then there exists a subwalk $C = (a_i, r_i, \ldots, a_{j+1})$ (with $i\leq j$) that is an oriented cycle. But then \begin{align*}
        W' = (a_0, r_0, \ldots, a_{i-1}, r_{i-1}, a_i = a_{j+1}, r_{j+1}, \ldots, a_{n-1}, r_n, a_{n})
    \end{align*} is a smaller closed oriented walk (it has length $n-(j-i+1)<n$). So by the induction hypothesis, we get that $\gamma(A) \mid l(W')$. We also have $l(W) = l(W') + l(C)$ and by the argument from the previous case, $\gamma(A) \mid l(C)$. So we have $\gamma(A) \mid l(W)$.
\end{itemize}
Using induction, we conclude that $\gamma(A) \mid l(W)$ for all closed oriented walks $W$ in $A$, which is what we wanted to show.
\qed


We are now going to prove the lemma that is the cornerstone for our limitative result on the expressive power of left query algorithms. Before we do that we need to establish some basic facts.
\par 

For a given signature $\tau = \{R_1, \ldots, R_n\}$, we let $\mathbf{1}_\tau$ denote the complete singleton structure of that signature, namely \begin{align*}
    \mathbf{1}_\tau \coloneqq (\{0\}, (\{0\}^{r_i})_{R_i \in \tau}).
\end{align*}
For digraphs, this is simply the structure consisting of a single loop. If the signature is clear from the context, we usually drop the subscript. 
\par 
The \emph{direct product} of two structures $\mathfrak A = (A, (R_i^\mathfrak A)_{i\in \{1,\ldots,n\}})$ and $\mathfrak B = (B, (R_i^\mathfrak B)_{i\in \{1,\ldots,n\}})$ is defined with
\[\mathfrak A \otimes \mathfrak B \coloneqq (A \times B, R_i^{\mathfrak A \otimes \mathfrak B})\]
where 
\[R_i^{\mathfrak A \otimes \mathfrak B} \coloneqq \{((a_1, b_1), \ldots, (a_{r_i}, b_{r_i})) : (a_1, \ldots, a_{r_i}) \in R_i^\mathfrak A \hspace{6pt}\text{and}\hspace{6pt} (b_1, \ldots, b_{r_i}) \in R_i^\mathfrak B \}.\]
The following observations are easy to prove:
\begin{proposition}\hspace{0 cm}
\label{product rules}
    \begin{enumerate}[(i)]
        \item For any structure $H$ and natural number $r$ we have $(r\cdot \mathbf{1})\otimes H \cong r \cdot H$.
        \item For any natural number $n$ we have $\mathsf{C}_n \otimes \mathsf{C}_n \cong n \cdot \mathsf{C}_n$.
        \item For any structures $H, A,B$ we have $\hom(H, A\otimes B) = \hom(H,A)\cdot \hom(H, B)$.
    \end{enumerate}
\end{proposition}

We can now prove:

\homLemma*
\proof 
First we note that $\hom(A, n\cdot \mathbf{1}) = n^{c(A)}$. 
From Proposition \ref{product rules} we get $\mathsf{C}_n\otimes \mathsf{C}_n \cong n\cdot \mathsf{C}_n \cong (n\cdot \mathbf{1}) \otimes \mathsf{C}_n$. 
Therefore \begin{align*}
    \hom(A, \mathsf{C}_n) \cdot \hom(A, \mathsf{C}_n) 
    &= \hom(A, \mathsf{C}_n \otimes \mathsf{C}_n) \\
    &= \hom(A, n \cdot \mathsf{C}_n) \\
    &= \hom(A, n\cdot \mathbf{1}) \cdot \hom(A, \mathsf{C}_n),
\end{align*} so if $\hom(A, \mathsf{C}_n) \neq 0$ then $\hom(A, \mathsf{C}_n) = \hom(A, n\cdot \mathbf{1}) = n^{c(A)}$.
We then get \begin{align*}
    \hom(A, m\cdot \mathsf{C}_n) 
    &= \hom(A, (m\cdot \mathbf{1}) \otimes \mathsf{C}_n)\\
    &= \hom(A, m\cdot \mathbf{1}) \cdot \hom(A, \mathsf{C}_n)\\
    &= \begin{cases}
        0 &\If \hom(A, \mathsf{C}_n) = 0\\
        m^{c(A)}\cdot n^{c(A)} &\If \hom(A,\mathsf{C}_n) \neq 0
    \end{cases}\\
    &= \begin{cases}
            0 &\If n \nmid \gamma(A) \\
            (m\cdot n)^{c(A)} &\If n \mid \gamma(A)
        \end{cases}
\end{align*}
where the last step follows from Lemma \ref{girth-prop}
\qed







\section{Proof of Theorem \ref{n-ary-better-corollary}}
\label{proof-of-nary-thm}
Theorem \ref{better-corollary} shows that for every signature containing a binary relation, there exists a class of structures with that signature that is not decided by an adaptive left $k$-query algorithm over $\N$ for any $k$.
The key step in the proof of that result is Lemma \ref{hom-lemma}.
In this section, we extend this result to any signature that contains an $n$-ary relation with $n\geq2$.
We do this by emulating the symmetry of directed cycles to get an $n$-ary analogue to Lemma \ref{hom-lemma}.

\begin{definition}
    The $n$-ary cycle of length $d$ is defined with \begin{align*}
        \mathsf{C}_d^n \coloneqq (\{0,\ldots, d-1\}, R)
    \end{align*} where \begin{align*}
        R = \{(i \!\!\!\pmod d, \ldots, i+ (n-1) \!\!\!\pmod d) : i \in \{0,\ldots, d-1\}\}.
    \end{align*}
\end{definition}

For a structure $\A = (A, R)$ with one $n$-ary relation, we define $\A^* \coloneqq (A, R^*)$ where $R^*$ is the binary relation defined with: $R^*(a,b)$ holds if and only if there exists an $i$ and elements $a_1,\ldots,a_{i-1}, a_{i+2},\ldots, a_n$ such that \begin{align*}
    R(a_1,\ldots,a_{i-1}, a, b, a_{i+2}, \ldots, a_n).
\end{align*}
Note that $(\mathsf{C}_d^n)^*\cong \mathsf{C}_d$.
We can now prove:
\begin{lemma}
    \label{n-ary-transformation-lemma}
    Let $\A = (A, R)$ be a structure where $R$ is an $n$-ary relation. A function $f: \A \to \mathsf{C}_d^n$ is a homomorphism if and only if $f: \A^* \to \mathsf{C}_d$ is a homomorphism.
\end{lemma}
\proof 
First, assume $f$ is a homomorphism from $\A$ to $\mathsf{C}_d^n$ and let $R^*(a,b)$ be given. Then there exists $i$ and elements $a_j$ for $j\in \{1,\ldots, n\}\setminus\{i,i+1\}$ such that $R(a_1,\ldots,a_{i-1}, a, b, a_{i+2}, \ldots, a_n)$. Then we get \begin{align*}
        R(f(a_1),\ldots,f(a_{i-1}), f(a), f(b), f(a_{i+2}), \ldots, f(a_n))
\end{align*}
and therefore $R^*(f(a), f(b))$, so $f$ preserves $R^*$.\par 
For the other direction, assume $f$ preserves $R^*$ and let $R(a_1, \ldots, a_n)$ be given. For each $i \in \{1,\ldots, n-1\}$ we then have $R^*(a_i,a_{i+1})$, so $R^*(f(a_i), f(a_{i+1}))$ which means that $f(a_i)+1 = f(a_{i+1})\pmod d$. Since this holds for every $i$ we have \begin{align*}
    f(a_{j+1}) = f(a_1)+ j \!\!\! \pmod d
\end{align*} for each $j \in \{0,\ldots, n-1\}$. So indeed $R(f(a_1), \ldots, f(a_n))$ and we have shown that $f$ preserves $R$.
\qed

The following now immediately follows from Lemmas \ref{n-ary-transformation-lemma} and \ref{girth-prop}.
\begin{lemma}
    \label{n-ary-girth-lemma}
    Let $\A = (A, R)$ with $R$ $n$-ary. Then $\A \to \mathsf{C}_d^n$ if and only if $d\mid \gamma(\A^*)$.
\end{lemma}

We then obtain the analogue of Lemma \ref{hom-lemma} for structures with one $n$-ary relation.

\begin{lemma}
    \label{n-ary-hom-lemma}
    For every $\A= (A, R)$ with $R$ an $n$-ary relation and all positive integers $d,m$ we have \begin{align*}
        \hom(\A, m\cdot \mathsf{C}_d^n) = \begin{cases}
            0 &\If d \nmid \gamma(\A)\\
            (m\cdot d)^{c(\A)} &\If d\mid \gamma(\A)
        \end{cases}.
    \end{align*}
\end{lemma}
\proof 
In the same way as in Proposition \ref{product rules} we have that $\mathsf{C}_d^n \otimes \mathsf{C}_d^n \cong d \cdot \mathsf{C}_d^n$ by observing that the diagonal lines in the product form cycles.
Then we have $\mathsf{C}_d^n \otimes \mathsf{C}_d^n \cong d \cdot \mathsf{C}_d^n \cong (d\cdot \mathbf{1})\otimes \mathsf{C}_d^n$. Using this and Lemma \ref{n-ary-girth-lemma} the proof follows in the same way as the proof of Lemma \ref{hom-lemma}.
\qed
\par 
It is now easy to see that we can use the same proofs as before to prove analogues of Theorem \ref{main-theorem}, Corollary \ref{intermediate-corollary} and Theorem \ref{better-corollary}. 
\par 
The attentive reader might have noticed that the hypothesis $n\geq 2$ is not assumed in Lemma~\ref{n-ary-hom-lemma}.
Indeed, the lemma also holds in the case $n = 1$. 
However, the analogues of Theorem \ref{main-theorem}, Corollary \ref{intermediate-corollary}, and Theorem \ref{better-corollary} do not extend to this case. The reason is that if $n=1$ we have $\mathsf{C}_d^n \cong d \cdot \mathsf{C}_1^n$, whereas for all $n\geq 2$ and all $m>1$ we have that $\mathsf{C}_{m\cdot d}^n \ncong m\cdot \mathsf{C}_d^n$. Therefore we can only establish the analogues of these results for $n$-ary relations with $n\geq2$. In particular, we obtain:
\nAryBetterCorollary*


Finally, we also prove the claim that every class of structures with a signature containing only unary relation symbols is decided by a left bounded query algorithm over $\N$.
\begin{theorem}
\label{thm:unary-is-decidable}
    Every class of structures with signature $\tau = \{P_1, \ldots, P_k\}$, where each $P_i$ is a unary relation symbol, is decided by a non-adaptive left $2^k$-query algorithm over $\N$.
\end{theorem}
\begin{proof}
    For each subset $S \subseteq \tau$ let $F_S \coloneqq (\{0\}, (P_i^{F_S})_{i = 1}^k)$ where 
    \[P_i^{F_S} = \begin{cases}
        \{0\} &\If P_i \in S \\
        \varnothing &\If P_i \notin S
    \end{cases}.
    \]
    In words, $F_S$ is the singleton structure satisfying the predicates in $S$ and no others.
    Querying $\hom(F_S, A)$ for each $S$ gives information about the number of elements in $A$ satisfying each Boolean combination of the predicates in $\tau$.
    This information determines $A$ up to isomorphism and therefore suffices to classify $A$ correctly.
\end{proof}



\section{Proofs of Theorems About Left Query Algorithms over $\B$}
\label{appendix:proofs-from-unb-over-B}

Here, we first prove the correctness of the topological characterization of the expressive power of adaptive left unbounded query algorithms over $\B$.
\topologicalCharacterization*

\proof\hspace{0cm}
\begin{itemize}
    \item[$\Rightarrow$:] Let $G$ be an adaptive left unbounded query algorithm over $\B$ that decides $\C$. We want to show that $\C$ is clopen. Let $A \in \C$. Now $\sigma(A, G)$ is finite so there exist $A_0, \ldots , A_n$ such that \begin{align*}
        \sigma(A, G) = (\hom_\B(A_0, A) , \ldots, \hom_\B(A_n, A)).
    \end{align*}
    Let \begin{align*}
        U_A \coloneqq \bigcap_{A_i \to A} \up{A_i} \cap \bigcap_{A_i \nrightarrow A} \mathsf{FIN}(\tau) \setminus \up {A_i}.
    \end{align*}
    Then indeed $U_A$ is a basis element such that $A \in U_A$. Now for $A' \in U_A$ we have \begin{align*}
        (\hom_\B(A_0, A') , \ldots, \hom_\B(A_{n'}, A')) = (\hom_\B(A_0, A) , \ldots, \hom_\B(A_{n'}, A))
    \end{align*} for every $n'\leq n$. The computation path of $G$ on $A'$ is thus the same as the computation path on $A$, i.e. $\sigma(A', G) = \sigma(A, G)$.
    It therefore follows that the algorithm accepts $A'$ since it accepts $A$, and thus $U_A \subseteq \C$. We have now shown that $\C = \bigcup_{A \in \C} U_A$, so it is open. If $\C$ is decided by an adaptive left unbounded query algorithm over $\B$ then so is $\C^c$ (by switching \textsf{YES} and \textsf{NO} in deciding step of the algorithm). Our argument therefore also shows that $\C^c$ is open, so $\C$ is clopen.

    \item[$\Leftarrow$:] Let $\C \subseteq \mathsf{FIN}(\tau)$ be clopen. Let $A_0, A_1, A_2, \ldots$ be an enumeration of all structures with signature $\tau$ up to isomorphism. For any $\sigma = (\sigma_0, \ldots, \sigma_n) \in \B^{<\omega}$ we have a corresponding basis element\begin{align*}
        U_\sigma = \bigcap_{{\substack{i \leq n \\ \sigma_i = 1}}} \up{A_i} \cap \bigcap_{{\substack{i \leq n \\ \sigma_i = 0}}} \mathsf{FIN}(\tau)\setminus \up{A_i}.
    \end{align*}
    Moreover, if $A$ is the target structure defining $\sigma$, so \begin{align*}
        \sigma = (\hom_\B(A_0, A) , \ldots, \hom_\B(A_n, A))
    \end{align*}
    then we have that $A \in U_\sigma$.
    We now define the following algorithm: \begin{align*}
        G( \sigma) = \begin{cases}
            \mathsf{YES} &\If U_\sigma \subseteq \C \\
            \mathsf{NO} &\If U_\sigma \subseteq \C^c \\
            A_{\abs{\sigma}} &\hspace{6 pt}\text{otherwise}
        \end{cases}.
    \end{align*}
    If $\sigma = (\hom_\B(A_0, A) , \ldots, \hom_\B(A_n, A))$ and $U_\sigma \subseteq \C$ then clearly $A \in \C$. Similarly, if $U_\sigma \subseteq \C^c$ then $A \notin \C$ so the algorithm always classifies correctly when it terminates. To see that it always terminates we note that for any $A$ we have either $A \in \C$ or $A \in \C^c$. Assume, without loss of generality, that $A \in \C$. Then, since $\C$ is open, there is a basis element \begin{align*}
        U = \bigcap_{i = 0}^k \up{B_i} \cap \bigcap_{i= 0}^m \mathsf{FIN}(\tau)\setminus\up{D_i}
    \end{align*} such that $A \in U \subseteq \C$. Now, there exists an $n$ such that $B_i, D_j \in \{A_0, \ldots, A_n\}$ for all $i = 0,\ldots, k$ and $j = 0,\ldots, m$ (here we do not distinguish between isomorphic structures). 
    So, then indeed $A \in U_\sigma \subseteq U \subseteq \C$ for $\sigma = (\hom_\B(A_0, A) , \ldots, \hom_\B(A_n, A))$. This shows that the algorithm terminates. The argument is exactly the same for $A \in \C^c$. We have thus shown that $\C$ is decided by an adaptive left unbounded query algorithm over $\B$.
\end{itemize}
\qed
\par


We now show how to use the topological characterization to prove the following.
\datalogUnboundedLqaThm*
\proof 
Since $\C$ is homomorphism-closed it follows directly that $\C = \bigcup_{A \in \C} \up{A}$. Since $\up{A}$ is open for each $A$, it follows that $\C$ is open.
We now turn to proving (ii).
The right-to-left direction is immediate since $\bigcup_{j=0}^n \up{A_{i,j}}$ are closed sets.
For the other direction, we assume $\C$ is closed and thus clopen. 
Since $\C$ is closed and the basis is clopen we have that $\C$ is an intersection of basis elements:
\begin{align}
\label{cequation}
    \C = \bigcap_{i \in I} \qty(\bigcup_{j = 0}^{n_i} \up{B_{i,j}} \cup \bigcup_{j = 0}^{k_i} \mathsf{FIN}(\tau)\setminus\up{D_{i,j}}).
\end{align}
In fact, we can assume that $B_{i,j}$ is connected for each $(i,j)$:\par 
Each $B_{i,j}$ can be written as $B_{i,j} = A_1\oplus \ldots \oplus A_n$ where $A_k$ is connected for each $k$. Then $\up{B_{i,j}} = \bigcap_{k=1}^n \up{A_k}$ since $\oplus$ is a least upper bound operation in the lattice. Using the distributive law it is clear that each term $\bigcup_{j = 0}^{n_i} \up{B_{i,j}} \cup \bigcup_{j = 0}^{k_i} \mathsf{FIN}(\tau)\setminus\up{D_{i,j}}$ can be written in conjunctive normal form as: \begin{align*}
    \bigcap_{k = 0}^n \qty(\bigcup_{j = 0}^{n_i'} \up{A_{i,k,j}} \cup \bigcup_{j = 0}^{k_i'} \mathsf{FIN}(\tau)\setminus\up{D'_{i,k,j}})
\end{align*}
where each $A_{i,k,j}$ is connected. Thus we can write 
\begin{align*}
    \C =  \bigcap_{i \in I} \bigcap_{k = 0}^n \qty(\bigcup_{j = 0}^{n_i'} \up{A_{i,k,j}} \cup \bigcup_{j = 0}^{k_i'} \mathsf{FIN}(\tau)\setminus\up{D'_{i,k,j}}).
\end{align*} The outer intersections can be taken together to form an equation of the form (\ref{cequation}) where each $B_{i,j}$ is connected.
\par 
We can now assume equation (\ref{cequation}) holds and all $B_{i,j}$'s are connected. If \begin{align*}
     \C = \bigcap_{i \in I} \bigcup_{j = 0}^{n_i} \up{B_{i,j}}
\end{align*} then we are done. Otherwise there exists a structure $H\in \C$ such that $H \notin \bigcup_{j = 0}^{n_i} \up{B_{i,j}}$ for some $i$. Since $\C$ is homomorphism-closed we also have that $H' \coloneqq H\oplus \bigoplus_{j=0}^{k_i} D_{i,j} \in \C$, but $H' \notin \bigcup_{j = 0}^{k_i} \mathsf{FIN}(\tau)\setminus\up{D_{i,j}}$. This means that we must have $H' \in \bigcup_{j = 0}^{n_i} \up{B_{i,j}}$, so for some $j$ we have $B_{i,j}\rightarrow H'$. Then, since $B_{i,j}$ is connected and $B_{i,j} \nrightarrow H$, we must have $B_{i,j} \to D_{i,j'}$ for some $j'$. But then $\up{D_{i,j'}} \subseteq \up{B_{i,j}}$ so \begin{align*}
    \up{B_{i,j}} \cup (\mathsf{FIN}(\tau)\setminus\up{D_{i,j'}}) = \mathsf{FIN}(\tau)
\end{align*} and thus \begin{align*}
    \bigcup_{j = 0}^{n_i} \up{B_{i,j}} \cup \bigcup_{j = 0}^{k_i} \mathsf{FIN}(\tau)\setminus\up{D_{i,j}} =  \mathsf{FIN}(\tau). 
\end{align*}
We can therefore define 
\[I' \coloneqq \{ i \in I : \bigcup_{j = 0}^{n_i} \up{B_{i,j}} \cup \bigcup_{j = 0}^{k_i} \mathsf{FIN}(\tau)\setminus\up{D_{i,j}} \neq  \mathsf{FIN}(\tau)\}\]
and obtain \begin{align*}
    \C =  \bigcap_{i \in I'} \bigcup_{j = 0}^{n_i} \up{B_{i,j}}
\end{align*}
as desired.
\qed
\par 
We now use the topological characterization to prove Theorem \ref{thm:main-CSP}.
\mainCSP*
\begin{proof}
    If $\C$ is decided by a non-adaptive left query algorithm over $\B$ then it is clearly also decided by an adaptive one.
    For the other direction, first assume $\C = [A]_{\leftrightarrow}$ is decided by an adaptive left unbounded query algorithm over $\B$. Then $[A]_{\leftrightarrow}$ is clopen, so it is a union of basis elements. Since it is a singleton modulo homomorphic equivalence, it must be a union of a single basis element. It is thus an intersection of $k$ subbasis elements, which correspond to homomorphism queries. Thus it is clear that $[A]_{\leftrightarrow}$ is decided by a non-adaptive left $k$-query algorithm.
    \par
    Now assume $\C = \CSP(A)$ is decided by an adaptive left unbounded query algorithm over $\B$. Note that such an algorithm can be turned into an adaptive left unbounded query algorithm over $\B$ for $[A]_{\leftrightarrow}$ by also querying for the existence of a homomorphism from $A$. If such a homomorphism exists and the target structure is in $\CSP(A)$, then the algorithm accepts. From the above it therefore follows that $[A]_{\leftrightarrow}$ is also decided by a non-adaptive left query algorithm over $\B$. 
    Proposition 4.4 in ten Cate et al. \cite{ten2024homomorphism} states that $[A]_{\leftrightarrow}$ is decided by a non-adaptive left query algorithm over $\B$ if and only if $\CSP(A)$ is.
    Thus we have that $\CSP(A)$ is also decided by a non-adaptive left query algorithm over $\B$. 
\end{proof}




For the proof of the following theorem, we use an example of a $\CSP$ that is not first-order definable but has a simple Datalog program defining its complement.
\monadicDatalog*
\begin{proof}
    Let $\tau= \{R, P, Q\}$ be a signature with $R$ a binary relation while $P$ and $Q$ are unary. Define the structure $A\coloneqq \{ \{0,1\}, R^{A}, P^A, Q^A\}$ with $R^{A} \coloneqq \{(0,0), (1,1)\}$, $P_A = \{0\}$ and $Q_A=\{1\}$. A structure $B$ is an element of $\CSP(A)$ if and only if there is no undirected path from an element in $P^B$ to an element in $Q^B$. It is a standard application of the Ehrenfeucht-Fra\"{i}sse method to show that this is not first-order definable.
    It then follows from Theorem \ref{cor:csp-FO} that the complement of $\CSP(A)$ is not decided by an adaptive left unbounded query algorithm over $\B$.
    However, this class is defined by the following monadic linear Datalog program:
    \[
        \begin{array}{lll}
            X(x) &\leftarrow & P(x) \\
            X(y) & \leftarrow & X(x), R(x,y)\\
            X(y) & \leftarrow & X(x), R(y,x)\\
            Ans() & \leftarrow & X(y), Q(y)
        \end{array}
    \]
\end{proof}





\section{Proofs of Theorems About Right Query Algorithms}
\label{appendix:rqa-thm}
The goal of this section is to prove the theorems about right query algorithms. We begin with the following:

\rightQueryTheorem*
This theorem follows almost immediately from the following result, which is a variation of a result by Wu and Kolaitis (Theorem 5.38 in \cite{wu2023study}). The proof is exactly the same as their proof so we leave it out.

\begin{lemma}
\label{Wu}
    For every $n>0$ and every signature $\tau$, there exists a structure $F(n,\tau)$ of signature $\tau$ such that for every two structures $H,H'$ with signature $\tau$ and of size $n$ we have \begin{align*}
        H\cong H' \text{ if and only if } \hom(H, F(n,\tau)) = \hom(H', F(n,\tau)).
    \end{align*}
\end{lemma}

\par 
\begin{proof}[Proof of Theorem \ref{right-query-theorem}]
Let $\tau$ be a signature. Let $\mathfrak{2}_\tau$ be the complete structure with domain of size 2 and signature $\tau$. Concretely, $\mathfrak{2}_\tau \coloneqq (\{0,1\}, (R_\mathfrak{2})_{R \in \tau})$ where \begin{align*}
    R_\mathfrak{2} = \{0,1\}^{m_R}
\end{align*} where $m_R$ is the arity of $R$. \par 
Then, for any structure $H$ with signature $\tau$ we have \begin{align*}
    \hom(H, \mathfrak{2}_\tau) = 2^\abs{H}.
\end{align*}
Our algorithm thus runs as follows:
Given input $H$, query $\hom(H, \mathfrak{2}_\tau)$ to obtain $\abs{H}$. Then query $\hom(H, F(\abs{H}, \tau))$. 
\par 
By Lemma \ref{Wu} this determines the structure $H$ up to isomorphism. 
Thus every input $A$ has a unique computation path $\sigma(A)$ up to this point. We can thus set 
\[G(\sigma(A)) \coloneqq \begin{cases}
    \textsf{YES} &\If A \in \C \\
    \textsf{NO} & \If A \notin \C
\end{cases}\]
where $\C$ is the class we are trying to decide.
\end{proof}

\medskip\par 
We now turn towards proving Theorem \ref{unbounded-helps-rqa}.
\unboundedHelpsRqa*

Before we prove the theorem we state a few lemmas.

\begin{lemma}[{Proposition 1.13 in \cite{hell2004graphs}}]
    \label{path-lemma} 
    A digraph $H$ has no oriented cycle with non-zero net length if and only if $H \to P_{\abs{H}-1}$.
\end{lemma}

\begin{lemma}
\label{rqa-unb-lemma1}
Let $A$ be a finite directed graph. We have that $A$ has no oriented cycle with non-zero net length if and only if there exists $n>0$ such that $\hom(A, \mathsf{P}_n) >0$.
\end{lemma}
\proof \hspace{0cm}
\begin{itemize}
    \item[$\Rightarrow$:] Since the net length of oriented walks is preserved under homomorphisms and the net length of the longest oriented walk in $\mathsf{P}_n$ is $n$, we see that if $A \to \mathsf{P}_n$ then $A$ has no oriented walk with net length $>n$. Then indeed $A$ has no oriented cycle with positive net length (and thus no oriented cycle with non-zero net length). 
    \item[$\Leftarrow$:] If $A$ has no oriented cycles with positive net length then it follows from Lemma \ref{path-lemma} that $A \to P_{\abs{A}-1}$.
\end{itemize}
\qed


\begin{lemma} 
\label{rqa-unb-lemma2}
Let $A$ be a finite directed graph. We have that $A$ has an oriented cycle with non-zero net length if and only if there exists $n>0$ such that $\hom(A, \mathsf{C}_n)=0$.
\end{lemma}
\proof\hspace{0cm}
\begin{itemize}
    \item[$\Rightarrow$:] If $\hom(A, \mathsf{C}_n) = 0$, then by Lemma \ref{girth-prop} we have $n \nmid \gamma(A)$. In particular $\gamma(A) \neq 0$, so $A$ has an oriented cycle with non-zero net length. \par 
    \item[$\Leftarrow$:] If $A$ has a oriented cycle of non-zero net length then $\gamma(A) \neq 0$. But then $\gamma(A) + 1 \nmid \gamma(A)$ so by Lemma \ref{girth-prop} we have $\hom(A, \mathsf{C}_{\gamma(A)+1}) = 0$.
\end{itemize}
\qed 



Surprisingly, essentially the same unbounded algorithm as we used to prove Theorem \ref{leftUnboundedMoreExpressive} works here.

\begin{proof}[Proof of Theorem \ref{unbounded-helps-rqa}]
We first show that the class $\C$ of all digraphs that have an oriented cycle with non-zero net length can be decided by an adaptive right unbounded query algorithm over $\B$.
The algorithm runs as follows:
Let $A$ be the given input.
For $n = 1,2, \ldots$ query $\hom_\B(A, \mathsf{P}_n)$ and $\hom_\B(A, \mathsf{C}_n)$. If at any point $\hom_\B(A, \mathsf{P}_n) = 1$ then halt and output \textsf{NO}. If at any point $\hom_\B(A, \mathsf{C}_n) = 0$ then halt and output \textsf{YES}. \par 
It follows from Lemmas \ref{rqa-unb-lemma1} and \ref{rqa-unb-lemma2} that on every input, this algorithm halts and produces the correct outcome.

\smallskip \par 
We now show that the class $\C$ cannot be decided by a non-adaptive right $k$-query algorithm over $\B$ and thus not by an adaptive right $k$-query algorithm over $\B$. \par 
Let $(\mathcal F, X)$ be a non-adaptive right $k$-query algorithm. Let 
\[m \coloneqq \max (\{ \abs{F} : F \in \mathcal F\}),\]
so $m\geq \abs{F}$ for every $F \in \mathcal F$. Then, since the lengths of directed walks are preserved under homomorphism, it holds that for any $F \in \mathcal F$ we have $P_{m} \to F$ if and only if $F$ has a directed cycle. 
Also, if $F$ has a directed cycle, then that cycle has length $\leq m$ so $\mathsf{C}_{m!} \to F$. It is also clear that if $\mathsf{C}_{m!} \to F$ then $F$ must have a directed cycle. Thus $\mathsf{C}_{m!} \to F$ if and only if $F$ has a directed cycle. We have thus shown that for $F \in \mathcal{F}$ we have\begin{align*}
    P_{m} \to F \quad \text{if and only if}\quad \mathsf{C}_{m!} \to F.
\end{align*} So the class $\C'$ that the algorithm decides either contains both $P_{m}$ and $\mathsf{C}_{m!}$ or neither of them. In both cases $\C' \neq \C$ so the algorithm does not decide the class $\C$.
\end{proof}

The class from the above result is Datalog definable:
\begin{theorem}
    \label{thm:non-zero-net-length-is-Datalog}
    The class of all digraphs that have an oriented cycle with non-zero net length is Datalog definable.
\end{theorem}
\begin{proof}
    A Datalog program defining this class is the following:
    \[\begin{array}{ccc}
        X(a,b) & \leftarrow & a=b \\
        X(a,b) & \leftarrow & X(a', b'), R(a', a), R(b',b) \\
        X(a,b) & \leftarrow & X(a', b'), R(a, a'), R(b, b')\\
        X(a,b) & \leftarrow & X(a,c), X(c,b)\\
        \\
        Y(a,b) & \leftarrow & R(a, b)\\
        Y(a,b) & \leftarrow & Y(a, c), X(c, b) \\
        Y(a,b) & \leftarrow & X(a, c), Y(c, b)\\
        Y(a,b) & \leftarrow & Y(a, c), Y(c, b)\\
        \\
        Ans() & \leftarrow & Y(a, a)    \\
    \end{array}\]
    To see that this program does indeed define the class of digraphs that have an oriented cycle with non-zero net length, we begin by showing that the IDB $X$ defines the relation \begin{align}
    \label{eq:X-fact}
        X(a,b) \iff \text{there is an oriented walk from $a$ to $b$ with net length 0}.
    \end{align}
    The left-to-right direction is clear. To see the other direction, we use induction on the length of walks of net length 0.
    Let $P$ be any walk of length $2n$ but net length 0. 
    We have a few cases: \begin{itemize}
        \item If $P$ is of the form $(a_0, -, a_1, r_1, \ldots, a_{2n-1}, +, a_{2n})$ then $(a_1, r_1, \ldots, a_{2n-1})$ is an oriented walk of length $2(n-1)$ but net length 0, so by the induction hypothesis $X(a_1, a_{2n-1})$. It then follows from the second rule in the program that $X(a_0, a_{2n})$. 
        \item The case where $P$ is of the form $(a_0, +, a_1, r_1, \ldots, a_{2n-1}, -, a_{2n})$ is similar.
        \item Now assume $P = (a_0, +, a_1, r_1, \ldots, a_{2n-1}, +, a_{2n})$. Since it has net length 0 there must exist subwalks $Q$, $R$ and $Z$ of net length 0 such that \begin{align*}
            P = (a_0, +, a_1) \circ Q \circ (a_{i}, -, a_{i+1}) \circ R \circ (a_j, - , a_{j+1}) \circ Z \circ (a_{2n-1}, + , a_{2n}).
        \end{align*}
        (Namely, we pick $i$ as the smallest number such that $(a_0, +, \ldots, a_{i+1})$ is an oriented walk of net length 0 and we pick $j$ as the smallest number such that $(a_0, +, \ldots, a_{j+1})$ is an oriented walk of net length $-1$). By the induction hypothesis, $X(a_1, a_i)$, $X(a_{i+1}, a_j)$ and $X(a_{j+1} , a_{2n-1})$ hold. Using the rules, it is clear that we also have $X(a_0, a_{2n})$.
        \item The case where $P$ is of the form $(a_0, -, a_1, r_1, \ldots, a_{2n-1}, -, a_{2n})$ is similar.
    \end{itemize}
    We have now proved the bi-implication (\ref{eq:X-fact}). It is then easy to see that $Y(a,b)$ holds if and only if there is an oriented walk of positive net length from $a$ to $b$. Now we see that the program accepts if and only if there is a closed oriented walk of positive net length, which holds if and only if there is an oriented cycle of non-zero net length (this follows from our proof of Proposition \ref{girth-prop}).
\end{proof}


We now prove Theorem \ref{thm:rqa-unb-does-not-help}. We do it by proving a sequence of equivalences.
\begin{theorem}
    The following are equivalent:
    \begin{enumerate}[(i)]
        % \item $A$ has a downwards frontier
        \item $[A]_{\leftrightarrow}$ is decided by an adaptive right unbounded query algorithm over $\B$.
        \item $\up{A}$ is decided by an adaptive right unbounded query algorithm over $\B$.
        \item $[A]_{\leftrightarrow}$ is decided by a non-adaptive right query $k$-algorithm over $\B$ for some $k$.
        \item $\up{A}$ is decided by a non-adaptive right $k$-query algorithm over $\B$ for some $k$.
        \item $A$ is homomorphically equivalent to an acyclic structure.
    \end{enumerate}
\end{theorem}
\begin{proof}
    The equivalence of (iii), (iv), and (v) is Theorem 6.5 in ten Cate et al. \cite{ten2024homomorphism}. 
    It is easy to see that (iii) implies (i) and that (iv) implies (ii).
    Now, if $[A]_{\leftrightarrow}$ is clopen then it is a union of basis elements. Since it is a singleton modulo homomorphic equivalence, it must be a union of a single basis element. It is thus an intersection of $k$ subbasis elements, which correspond to right homomorphism queries. Thus it is clear that $[A]_{\leftrightarrow}$ is decided by a non-adaptive right $k$-query algorithm. This shows that (i) implies (iii).
    Now assume $\up{A}$ is decided by an adaptive right unbounded query algorithm over $\B$. Note that such an algorithm can be turned into an adaptive right unbounded query algorithm over $\B$ for $[A]_{\leftrightarrow}$ by also querying for the existence of a homomorphism to $A$. If such a homomorphism exists and the target structure is in $\up{A}$, then the algorithm accepts. This shows that (ii) implies (i).
\par 
    We have thus shown that all of the conditions are equivalent.
\end{proof}




